base = Path(__file__).resolve().parent
rows = []
group_materials = {
8:['carta a quadretti','matita','calcolatrice o formulario se utili al tuo compito'],
9:['carta a quadretti','matita','righello; compasso e squadra quando richiesti'],
10:['carta e matita','testo e dati riportati nella consegna'],
11:['carta e penna','copione riportato qui; persona che lo legga per le attività di ascolto','dizionario o modello linguistico quando utile'],
12:['carta e penna','testi nelle tre lingue riportati qui: lavora nella lingua che studi','persona che legga il copione per l’ascolto; dizionario quando utile'],
13:['carta e matita','righello','materiali semplici indicati nella consegna, se realizzi il progetto']}
coach_group = {
8:'Mostra una riga, poi fai scegliere al ragazzo il prossimo passaggio e chiedi di spiegarlo. Riduci i suggerimenti sulla procedura; mantieni calcolatrice, formulario e altri strumenti compensativi utili. Correttezza di un esempio non dimostra padronanza di ogni problema.',
9:'Distingui il ragionamento geometrico dalla precisione del tratto. Riduci indicazioni su ordine e scelta delle formule; lascia disponibili righe guida, strumenti e formulario. Un disegno riuscito non verifica da solo il calcolo o la dimostrazione.',
10:'Chiedi che cosa è stato osservato e che cosa è una spiegazione. Riduci le domande guida, mantenendo gli strumenti di lettura e registrazione utili. Gli esempi non sostituiscono procedure di laboratorio autorizzate; evita esperimenti con calore, corrente di rete o sostanze non previste.',
11:'Modella una frase e riduci progressivamente i suggerimenti sul suo contenuto; mantieni dizionario, scaletta e strumenti compensativi. Valuta separatamente comprensione, produzione e correttezza. Il copione scritto non verifica la comprensione orale: per quella serve una lettura realmente ascoltata.',
12:'Scegli la lingua effettivamente studiata e un modello di pronuncia del corso. Riduci i suggerimenti sul contenuto, mantenendo dizionario e scaletta utili. Non richiedere le tre lingue insieme: sono alternative. Il testo scritto non è una verifica dell’ascolto né della pronuncia.',
13:'Fai motivare una scelta e riduci i suggerimenti sull’ordine del lavoro; mantieni schemi e strumenti utili. Distingui funzionamento del progetto, qualità del disegno e manualità. Per realizzare oggetti usa solo materiali e strumenti autorizzati dal docente; le simulazioni su carta non attestano sicurezza di un dispositivo reale.'}

def r(id, goal, task, work, result, transfer, solution, steps, technique, checks, error, aid, home, category=None, difficulty=None, extra=''):
    group = int(id[1:3])
    category = category or ('discalculia' if group in (8,9) else 'dislessia' if group in (10,11,12) else 'trasversale')
    difficulty = difficulty or ('Confondo i dati mentre li ricopio' if category=='discalculia' else 'Perdo il punto mentre leggo' if category=='dislessia' else 'Perdo l’ordine dei passaggi')
    row = dict(id=id, goal=goal, materials=group_materials[group],
        techniques=[dict(name=technique[0],how=technique[1],why=technique[2]),
                    dict(name='Autoverifica con criteri',how='Prima di guardare la soluzione, controlla: '+'; '.join(checks)+'. Segna il punto da correggere.',why='Ti fa trovare il passaggio da rivedere invece di ripetere tutto senza sapere dove intervenire.')],
        example=dict(task=task,work=work,result=result),
        steps=[dict(title=s[0],do=s[1],help=s[2]) for s in steps],
        transfer=dict(task=transfer,check=solution),checks=checks,
        error=dict(wrong=error[0],why=error[1],fix=error[2]),
        home=[home,'Dopo due giorni riprova la prova nuova coprendo la soluzione; confronta e correggi un punto. Riprendila più avanti se resta incerto.','Se l’errore indicato ricompare o non capisci un passaggio, mostra al docente o al professionista la riga precisa e l’aiuto già provato.'],
        adaptations=[dict(stage=steps[0][0],difficulty=difficulty,categories=[category],signal='Osserva se durante questo passaggio servono riletture, ricopie o richiami ripetuti; non basta questo per attribuire una diagnosi.',aid=aid,preserve=goal,verify='Confronta due tentativi simili: conta i passaggi svolti correttamente e i richiami necessari. Mantieni l’aiuto se rende accessibile il compito.')],
        coach=coach_group[group]+(' '+extra if extra else ''),sources=['dunlosky2013','ies2007','eef2025','aid'])
    rows.append(row)

r('M08-01','Calcolare scegliendo un procedimento e controllarne il risultato.',
'Calcola 48 + 27 mentalmente e 326 − 178 in colonna. Spiega un controllo per ciascun risultato.',
['Scompongo 27 in 20 + 7: 48 + 20 = 68; 68 + 7 = 75.','Scrivo 326 − 178 allineando unità, decine e centinaia. Cambio una decina: 16 − 8 = 8; cambio una centinaia: 11 − 7 = 4; 2 − 1 = 1.','Controllo 75 − 27 = 48 e 148 + 178 = 326.'],
'48 + 27 = 75; 326 − 178 = 148. Scomposizione e incolonnamento producono risultati verificati dalle operazioni inverse.',
'Calcola 59 + 36 mentalmente e 402 − 185 in colonna. Scrivi anche i controlli.',
'59 + 30 + 6 = 95; 402 − 185 = 217. Controlli: 95 − 36 = 59; 217 + 185 = 402. Nel secondo calcolo lo zero delle decine richiede due cambi.',
[('Scegli il metodo','Sul tuo esercizio indica se conviene scomporre o incolonnare.','Per 48 + 27 puoi aggiungere prima le decine.'),('Registra i cambi','Scrivi un passaggio per riga e, in colonna, annota ogni cambio.','Lo zero non impedisce il cambio: puoi cambiare una centinaia in dieci decine.'),('Controlla con l’inversa','Esegui l’operazione inversa sul risultato.','Per una sottrazione somma risultato e numero sottratto.')],
('Scomposizione e valore posizionale','Separa le decine dalle unità nel calcolo mentale e usa colonne U-D-C nello scritto.','Rende visibile il valore delle cifre e i cambi.'),
['Le cifre sono nella colonna giusta','I cambi sono annotati','L’operazione inversa restituisce il dato iniziale'],
('326 − 178 = 252 perché sottraggo sempre la cifra più piccola dalla più grande.','La sottrazione ha un ordine: 6 − 8 richiede un cambio.','Riscrivi 326 come 2 centinaia, 11 decine e 16 unità: ottieni 148.'),
'Usa tre colonne già tracciate U-D-C; evidenzia solo la cifra che stai elaborando e registra il cambio vicino a essa.',
'Sui calcoli assegnati scegli un esempio mentale e uno scritto; conserva anche il controllo inverso.')

r('M08-02','Risolvere un’espressione rispettando parentesi e precedenze.',
'Risolvi 18 − 2 × (3 + 4) + 12 ÷ 3.',
['Calcolo la parentesi: 3 + 4 = 7. Riscrivo 18 − 2 × 7 + 12 ÷ 3.','Calcolo moltiplicazione e divisione: 18 − 14 + 4.','Eseguo addizione e sottrazione da sinistra: 4 + 4 = 8.'],
'Il valore dell’espressione è 8.',
'Risolvi 30 − (8 + 2) × 2 + 18 ÷ 6.',
'30 − 10 × 2 + 3 = 30 − 20 + 3 = 13.',
[('Segna le priorità','Cerchia le parentesi e sottolinea moltiplicazioni e divisioni nella tua espressione.','Lavora prima all’interno delle parentesi.'),('Riscrivi la riga','Sostituisci solo le operazioni appena risolte; ricopia gli altri simboli.','Non saltare da 18 − 14 + 4 alla risposta senza una riga di controllo.'),('Leggi i segni','Confronta riga per riga segni e numeri prima di continuare.','Tra operazioni della stessa priorità procedi da sinistra.')],
('Esempio commentato','Accanto a ogni riga scrivi “parentesi”, “moltiplicazioni/divisioni” o “addizioni/sottrazioni”.','Collega la regola al passaggio effettivo.'),
['La parentesi è svolta prima','Ogni numero non elaborato è riportato','L’ultima riga è un unico valore'],
('18 − 2 × 7 = 16 × 7.','Hai eseguito la sottrazione prima della moltiplicazione.','Calcola 2 × 7 = 14 e scrivi 18 − 14.'),
'Tieni la riga precedente visibile sopra quella nuova e usa un segnalino per confrontare un termine alla volta.',
'Su una tua espressione scrivi tre etichette di priorità e controlla una ricopiatura.')

r('M08-03','Riconoscere multipli e divisori e calcolare semplici potenze e radici.',
'Scrivi i multipli positivi di 6 fino a 30, i divisori positivi di 18, 3³ e √81.',
['Aggiungo 6 ogni volta: 6, 12, 18, 24, 30.','Cerco coppie con prodotto 18: 1 × 18, 2 × 9, 3 × 6.','3³ = 3 × 3 × 3 = 27. Per √81 cerco il numero non negativo il cui quadrato è 81: 9.'],
'Multipli: 6, 12, 18, 24, 30. Divisori: 1, 2, 3, 6, 9, 18. 3³ = 27; √81 = 9.',
'Scrivi i multipli positivi di 4 fino a 20, i divisori positivi di 12, 2⁴ e √49.',
'Multipli: 4, 8, 12, 16, 20. Divisori: 1, 2, 3, 4, 6, 12. 2⁴ = 16; √49 = 7.',
[('Distingui le richieste','Dividi il foglio in multipli, divisori, potenza e radice per il tuo compito.','Multipli: prodotti; divisori: divisioni senza resto.'),('Espandi i calcoli','Scrivi tutti i fattori della potenza e le coppie dei divisori.','L’esponente conta quante volte compare la base come fattore.'),('Controlla il quadrato','Eleva al quadrato la radice trovata.','9 × 9 deve restituire 81.')],
('Confronto di concetti','Affianca “multiplo di 6: 6 × 4 = 24” e “divisore di 18: 18 ÷ 6 = 3”.','Evita di scambiare le due relazioni.'),
['I divisori non lasciano resto','La potenza ha il numero corretto di fattori','La radice principale è non negativa'],
('3³ = 3 × 3 = 9.','Hai usato due fattori invece di tre.','Scrivi tre caselle con 3 e moltiplica: 27.'),
'Usa caselle separate per i fattori e una tabella di coppie per i divisori; il formulario delle potenze resta disponibile.',
'Per la tua pagina di esercizi separa i quattro tipi prima di calcolare.')

r('M08-04','Usare rapporti, proporzioni e percentuali indicando la base del confronto.',
'Una miscela contiene 2 bicchieri di succo e 3 di acqua. Mantieni il rapporto usando 6 bicchieri di succo. Poi calcola il 25% di 80 euro.',
['Il rapporto succo:acqua è 2:3. Da 2 a 6 moltiplico per 3, quindi acqua = 3 × 3 = 9 bicchieri.','La proporzione è 2:3 = 6:9; i prodotti incrociati sono entrambi 18.','25% di 80 = 25/100 × 80 = 20 euro; è anche un quarto di 80.'],
'Servono 9 bicchieri di acqua. Il 25% di 80 euro è 20 euro.',
'La ricetta usa 3 parti di avena e 2 di yogurt. Con 9 parti di avena, quanto yogurt serve? Calcola anche il 10% di 70 euro.',
'Yogurt: 6 parti; 3:2 = 9:6, prodotti incrociati 18. Il 10% di 70 euro è 7 euro.',
[('Etichetta i termini','Scrivi sopra ogni termine a che cosa si riferisce: succo o acqua, quota o totale.','Conserva lo stesso ordine in entrambi i rapporti.'),('Trova il fattore','Cerca per quanto cambia la quantità nota e applicalo all’altra.','Da 2 a 6 il fattore è 3.'),('Calcola e interpreta','Per la percentuale scrivi p/100 × totale e l’unità.','Il totale dell’esempio è 80 euro, non 25.')],
('Tabella di proporzionalità','Usa due righe, succo e acqua, con una freccia ×3 per entrambe.','Mostra che cambia la quantità, non il rapporto.'),
['L’ordine dei rapporti resta uguale','La percentuale si riferisce al totale corretto','La risposta ha unità e significato'],
('Con 6 bicchieri di succo servono 7 di acqua, perché aggiungo 4 a entrambi.','L’aggiunta non mantiene il rapporto 2:3.','Moltiplica entrambe le quantità per 3: 6 e 9.'),
'Prepara una tabella con nomi delle quantità e frecce; lascia visibile il totale prima di usare la calcolatrice.',
'Sulla tua ricetta o problema percentuale scrivi prima il totale e i nomi delle quantità.')

r('M08-05','Tradurre un testo in simboli rispettando l’ordine delle operazioni.',
'Indica con x un numero. Traduci “il doppio della somma del numero e 3” e “la somma del doppio del numero e 3”. Verifica con x = 4.',
['Nel primo testo sommo prima x e 3, poi raddoppio: 2(x + 3).','Nel secondo raddoppio x, poi aggiungo 3: 2x + 3.','Per x = 4 ottengo rispettivamente 2 × 7 = 14 e 8 + 3 = 11.'],
'Le traduzioni sono 2(x + 3) e 2x + 3; non significano la stessa cosa.',
'Traduci “il triplo della differenza fra un numero y e 2” e “il triplo di y diminuito di 2”. Calcola con y = 5.',
'3(y − 2) = 9; 3y − 2 = 13. Le parentesi rendono diverso l’ordine.',
[('Nomina l’incognita','Scrivi che cosa rappresenta la lettera nel tuo testo.','x è il numero intero della richiesta, non una cifra.'),('Disegna il raggruppamento','Racchiudi la somma o differenza che viene moltiplicata.','“Il doppio della somma” richiede parentesi.'),('Prova un valore','Sostituisci un numero semplice e racconta le operazioni nell’ordine.','Confronta 14 e 11 per vedere la differenza.')],
('Confronto di coppie minime','Affianca i due testi quasi uguali e sottolinea “della somma”.','Fa emergere il ruolo delle parole che cambiano il significato.'),
['La lettera ha una definizione','Le parentesi seguono il testo','La prova numerica rispetta lo stesso ordine'],
('“Il doppio della somma di x e 3” diventa 2x + 3.','Così solo x è raddoppiato.','Raggruppa x + 3: 2(x + 3).'),
'Leggi un blocco di parole alla volta e disegna due caselle per le azioni “somma” e “raddoppia”.',
'Nel tuo problema scrivi a parole l’ordine prima della formula.',category='dislessia')

r('M08-06','Costruire e controllare un problema con procedimento aritmetico o algebrico.',
'Tre quaderni uguali e una penna da 2 euro costano 11 euro. Quanto costa un quaderno? Risolvi prima aritmeticamente, poi con un’equazione.',
['Tolgo il costo della penna: 11 − 2 = 9 euro per i quaderni.','Divido 9 per 3: ogni quaderno costa 3 euro.','Definisco x = costo di un quaderno in euro. 3x + 2 = 11; 3x = 9; x = 3. Controllo 3 × 3 + 2 = 11.'],
'Un quaderno costa 3 euro; i due procedimenti rappresentano la stessa situazione.',
'Quattro biglietti uguali e una commissione unica di 3 euro costano 23 euro. Trova il prezzo di un biglietto con due procedimenti.',
'Aritmetica: (23 − 3)/4 = 5 euro. Algebra: 4x + 3 = 23, quindi x = 5. Controllo 4 × 5 + 3 = 23.',
[('Separa dati e domanda','Scrivi costi noti, quantità e ciò che devi trovare.','La penna è una sola: i 2 euro non vanno moltiplicati per 3.'),('Rappresenta il totale','Disegna tre caselle uguali e una da 2; poi scrivi l’equazione.','Le caselle uguali rappresentano quaderni dello stesso prezzo.'),('Rientra nel testo','Sostituisci il risultato nel totale e rispondi con l’unità.','La domanda è un prezzo, non il numero di quaderni.')],
('Doppia rappresentazione','Affianca il disegno delle quote e l’equazione 3x + 2 = 11.','Collega il calcolo ai dati e permette due vie di soluzione.'),
['La quantità incognita è definita','Il costo fisso compare una volta','Il prezzo trovato ricostruisce il totale'],
('11/3 = prezzo di un quaderno.','Il totale include anche la penna.','Sottrai prima 2, poi dividi per 3.'),
'Usa una scheda con “quantità”, “costo fisso”, “totale”, “domanda”; indica ciascun dato nel testo prima di copiarlo.',
'Su un tuo problema di acquisto disegna le quote uguali e una quota fissa.')

r('M08-07','Ridurre termini simili e verificare una semplice espressione letterale.',
'Riduci 3a + 2b − a + 4b. Poi calcola il valore per a = 2 e b = 1.',
['Raggruppo i termini in a: 3a − a = 2a.','Raggruppo i termini in b: 2b + 4b = 6b.','La forma ridotta è 2a + 6b. Sostituendo: 2 × 2 + 6 × 1 = 10; anche l’originale vale 6 + 2 − 2 + 4 = 10.'],
'3a + 2b − a + 4b = 2a + 6b; per i valori assegnati vale 10.',
'Riduci 5x − 2y − 3x + y e controlla per x = 3, y = 2.',
'2x − y; il valore è 6 − 2 = 4. Originale: 15 − 4 − 9 + 2 = 4.',
[('Segna la parte letterale','Nel tuo esercizio collega solo termini con lettere ed esponenti uguali.','a e b non sono termini simili.'),('Somma i coefficienti','Mantieni la lettera e calcola sui numeri con i loro segni.','Davanti a −a il coefficiente è −1.'),('Sostituisci due valori','Controlla la forma originale e quella ridotta con gli stessi numeri.','Un controllo numerico aiuta a trovare errori, ma non prova ogni identità.')],
('Raggruppamento per caratteristiche','Metti i termini in colonne a e b e conserva i segni.','Rende visibile ciò che può essere sommato.'),
['Sono uniti solo termini simili','Ogni segno è conservato','Il controllo numerico coincide'],
('3a + 2b = 5ab.','Hai sommato termini diversi e cambiato l’operazione in prodotto.','Lascia 3a + 2b come somma; riduci solo con altri termini in a o b.'),
'Usa due colonne etichettate per le lettere, con uno spazio davanti a ogni termine per il segno.',
'Su una tua espressione indica i gruppi di termini e verifica con valori piccoli.')

r('M08-08','Risolvere un’equazione di primo grado e verificarne la soluzione.',
'Risolvi 3x + 5 = 20 e verifica.',
['Sottraggo 5 a entrambi i membri: 3x = 15.','Divido entrambi i membri per 3: x = 5.','Sostituisco nel testo iniziale: 3 × 5 + 5 = 20.'],
'La soluzione è x = 5.',
'Risolvi 4y − 7 = 13 e verifica.',
'Aggiungo 7 a entrambi i membri: 4y = 20. Divido per 4: y = 5. Verifica: 4 × 5 − 7 = 13.',
[('Individua le operazioni','Sul membro con l’incognita segna moltiplicazione e termine aggiunto o sottratto.','Qui x è moltiplicato per 3 e poi si aggiunge 5.'),('Mantieni l’uguaglianza','Scrivi la stessa operazione sotto entrambi i membri.','Prima −5, poi ÷3.'),('Verifica nell’originale','Sostituisci il numero nell’equazione iniziale.','Verificare solo l’ultima riga non rileva gli errori precedenti.')],
('Bilancia delle operazioni','Scrivi esplicitamente 3x + 5 − 5 = 20 − 5 prima della riga ridotta.','Spiega perché l’uguaglianza è conservata.'),
['Ogni operazione riguarda entrambi i membri','L’incognita è isolata','La soluzione rende vera l’equazione iniziale'],
('3x + 5 = 20 diventa 3x = 25.','Per eliminare +5 serve sottrarre 5, non aggiungerlo.','Scrivi −5 su entrambi i membri: 3x = 15.'),
'Usa due colonne separate dal segno = e annota l’operazione in entrambe; tieni disponibile il modello della bilancia.',
'Su un’equazione assegnata conserva tutte le operazioni sui due membri e la verifica.')

r('M08-09','Stimare un risultato e riconoscere risposte implausibili.',
'Senza calcolare subito, stima 198 × 5. Poi calcola e valuta se 9900 potrebbe essere corretto.',
['Arrotondo 198 a 200: 200 × 5 = 1000.','Calcolo 198 × 5 = (200 − 2) × 5 = 1000 − 10 = 990.','990 è vicino a 1000; 9900 è circa dieci volte la stima e richiede un controllo.'],
'Risultato esatto 990. La stima 1000 permette di escludere 9900.',
'Stima 49 × 21 usando 50 × 20, poi calcola. Valuta la risposta 102,9.',
'Stima 1000; esatto 49 × (20 + 1) = 980 + 49 = 1029. 102,9 non è plausibile per due fattori vicini a 50 e 20.',
[('Arrotonda i dati','Scegli numeri vicini facili per il tuo calcolo.','Non cambiare 198 in 20: perderesti l’ordine di grandezza.'),('Calcola l’esatto','Esegui il procedimento scritto o usa lo strumento previsto.','Conserva la stima per confrontarla.'),('Spiega la distanza','Scrivi se il risultato è vicino, molto maggiore o molto minore della stima.','La stima segnala un errore possibile, non sostituisce l’esatto.')],
('Stima prima del calcolo','Scrivi 1000 prima di elaborare 198 × 5 e poi confronta.','Dà un riferimento indipendente dal risultato ottenuto.'),
['La stima usa numeri vicini','È distinta dal valore esatto','La plausibilità è motivata'],
('9900 è giusto perché l’ho letto sulla calcolatrice.','Anche un inserimento sbagliato produce una risposta.','Confronta con 1000 e reinserisci i fattori controllando le cifre.'),
'Scrivi stima ed esatto in due riquadri; usa una linea dei numeri o valori di riferimento per vedere la dimensione.',
'Prima di un calcolo lungo del tuo compito registra una stima ragionata.')

r('M08-10','Spiegare e confrontare due procedimenti corretti per lo stesso calcolo.',
'Calcola 25 × 16 in due modi: 25 × (10 + 6) e (25 × 4) × 4. Confronta vantaggi e risultato.',
['Distribuisco: 25 × 10 + 25 × 6 = 250 + 150 = 400.','Scrivo 16 = 4 × 4: (25 × 4) × 4 = 100 × 4 = 400.','Entrambi valgono 400; il secondo crea subito 100, il primo usa la scomposizione in decine e unità.'],
'400 in entrambi i casi. La scelta dipende da quali prodotti sai gestire con più chiarezza.',
'Calcola 12 × 15 usando 12 × (10 + 5) e (12 × 3) × 5. Spiega un vantaggio per ciascun metodo.',
'120 + 60 = 180; 36 × 5 = 180. Il primo usa decine e metà di dieci; il secondo scompone 15 in 3 × 5. I risultati coincidono.',
[('Nomina le regole','Per i tuoi due procedimenti indica distributiva o associativa.','Dividere 16 in una somma non è lo stesso che dividerlo in fattori.'),('Esplicita le righe','Mostra i prodotti intermedi e scrivi perché sono equivalenti.','Non basta dire “ho fatto a mente”.'),('Confronta la scelta','Scrivi un vantaggio concreto e verifica che il risultato sia comune.','Conta i passaggi che devi mantenere in mente.')],
('Auto-spiegazione','Dopo ogni riga spiega che cosa hai scomposto e quale operazione hai conservato.','Fa controllare il senso della trasformazione.'),
['I passaggi sono ricostruibili','La regola corrisponde alla trasformazione','Il confronto include un vantaggio concreto'],
('25 × (10 + 6) = 250 + 6.','La moltiplicazione per 25 riguarda entrambi gli addendi.','Scrivi 25 × 10 + 25 × 6.'),
'Usa due colonne per i metodi e confronta una riga alla volta; puoi spiegare a voce invece di scrivere tutta la motivazione.',
'Per un calcolo della tua pagina presenta due metodi e spiega quale ti aiuta di più.',category='trasversale')

r('M08-11','Individuare la prima riga errata e correggerne la regola.',
'Un alunno scrive 4 × (3 + 2) = 4 × 3 + 2 = 12 + 2 = 14. Trova la prima uguaglianza sbagliata e correggi.',
['La prima trasformazione è errata: manca 4 davanti al secondo addendo.','Applicando la distributiva: 4 × 3 + 4 × 2 = 12 + 8 = 20.','Controllo direttamente la parentesi: 4 × 5 = 20.'],
'La prima uguaglianza è sbagliata; il risultato corretto è 20.',
'Esamina 5 × (2 + 4) = 10 + 4 = 14. Indica la prima riga errata, correggi e controlla con la parentesi.',
'Prima trasformazione errata: 5 × 4 è diventato solo 4. Correzione: 10 + 20 = 30; controllo 5 × 6 = 30.',
[('Confronta due righe','Nel tuo svolgimento verifica la prima uguaglianza, poi passa alla seguente.','Un risultato sbagliato può dipendere da una riga molto precedente.'),('Nomina l’errore','Indica il termine o il segno cambiato e la regola violata.','Qui il fattore 4 deve moltiplicare anche 2.'),('Rifai da quel punto','Conserva ciò che è corretto e controlla con una via diversa.','Risolvere prima la parentesi fornisce un controllo indipendente.')],
('Analisi dell’errore','Segna la prima trasformazione non equivalente e riscrivi solo da lì.','Evita di attribuire l’errore all’intero compito.'),
['È indicata la prima riga errata','La spiegazione nomina la regola','La correzione è controllata con un altro metodo'],
('Correggo 12 + 2 in 20 senza cambiare la riga precedente.','La somma 12 + 2 vale davvero 14: l’errore è prima.','Ripristina 4 × 2 nella distribuzione.'),
'Copri le righe successive e metti a confronto solo due righe; indica con una freccia il termine trasformato.',
'Quando correggi un tuo esercizio segnala la prima riga diversa, non solo la risposta finale.')

r('M08-12','Usare calcoli, unità e controllo di convenienza in un acquisto quotidiano.',
'Hai 10 euro. Compri 3 pacchi a 2,40 euro l’uno e una gomma a 1,30 euro. Quanto spendi e quanto resto ricevi?',
['Tre pacchi costano 3 × 2,40 = 7,20 euro.','Aggiungo la gomma: 7,20 + 1,30 = 8,50 euro.','Resto: 10,00 − 8,50 = 1,50 euro. Controllo 8,50 + 1,50 = 10,00.'],
'Spesa 8,50 euro; resto 1,50 euro. Il denaro basta.',
'Hai 15 euro. Compri 4 biglietti a 2,75 euro e una cartellina a 1,60 euro. Calcola spesa e resto.',
'4 × 2,75 = 11,00; spesa 12,60 euro; resto 2,40 euro. 12,60 + 2,40 = 15,00.',
[('Organizza lo scontrino','Sul tuo problema separa quantità, prezzo unitario e costo della riga.','3 pacchi non significa 3 euro.'),('Somma le righe','Calcola i costi e allinea le virgole nella somma.','Scrivi 10,00 per il denaro disponibile.'),('Verifica il budget','Sottrai la spesa e ricomponi spesa più resto.','Un resto negativo indica che il denaro non basta.')],
('Tabella quantità-prezzo','Scrivi una riga per prodotto e una colonna per il costo totale.','Collega l’operazione al significato economico.'),
['Quantità e prezzo unitario sono distinti','Gli importi hanno due decimali coerenti','Spesa e resto ricostruiscono il budget'],
('2,40 + 1,30 = costo di tutti gli acquisti.','Hai contato un solo pacco.','Calcola prima 3 × 2,40.'),
'Usa uno scontrino con tre colonne già etichettate e calcolatrice; indica il budget in un riquadro separato.',
'Simula su carta un acquisto del tuo esercizio senza usare denaro reale.')

r('M09-01','Costruire una figura rispettando misure e uso degli strumenti.',
'Disegna un rettangolo ABCD con AB = 6 cm e BC = 3 cm. Usa righello e squadra; indica i vertici in ordine.',
['Traccio AB lungo 6 cm a partire dallo zero del righello.','Con la squadra costruisco perpendicolari ad AB in A e B; segno AD e BC di 3 cm sullo stesso lato.','Unisco D e C. Controllo CD = 6 cm, lati opposti paralleli e quattro angoli retti.'],
'Rettangolo con lati consecutivi 6 cm e 3 cm, vertici A-B-C-D lungo il bordo.',
'Disegna un rettangolo EFGH con EF = 4 cm e FG = 2 cm. Controlla lati e angoli.',
'EF = GH = 4 cm; FG = HE = 2 cm; quattro angoli retti. I vertici seguono il bordo e non sono incrociati.',
[('Traccia il primo lato','Misura il lato indicato nella consegna partendo dallo zero.','Non partire dal bordo di plastica del righello.'),('Costruisci le perpendicolari','Appoggia la squadra al primo lato e traccia due lati della stessa misura.','Mantieni la squadra ferma e segna prima i punti.'),('Chiudi e controlla','Unisci i punti finali e misura i lati opposti.','Se non coincidono, controlla prima gli angoli.')],
('Sequenza grafica','Segna sul foglio 1 lato, 2 perpendicolari, 3 chiusura prima di tracciare.','Riduce le decisioni simultanee durante il disegno.'),
['La misura parte dallo zero','I vertici sono in ordine sul bordo','Lati opposti e angoli rispettano la consegna'],
('Misuro 6 cm dalla tacca 1 alla tacca 6.','La distanza così è 5 cm.','Parti da 0 e arriva a 6, oppure da 1 a 7.'),
'Usa strumenti con presa stabile e foglio fissato; il professionista può tenere la squadra mentre tu scegli punti e misure.',
'Sul tuo disegno segna prima i punti e poi traccia una linea alla volta.',category='trasversale',difficulty='La squadra si muove mentre traccio la linea')

r('M09-02','Descrivere proprietà di figure piane e solidi senza confondere elementi.',
'Confronta un quadrato e un cubo: indica dimensione, lati o spigoli, vertici e, per il cubo, facce.',
['Il quadrato è una figura piana: 4 lati uguali, 4 vertici, 4 angoli retti.','Il cubo è un solido: 6 facce quadrate uguali, 12 spigoli e 8 vertici.','Distinguo lati del quadrato e spigoli del cubo; una faccia del cubo ha forma quadrata.'],
'Quadrato: piano, 4 lati e 4 vertici. Cubo: solido, 6 facce, 12 spigoli, 8 vertici.',
'Descrivi un rettangolo e un parallelepipedo rettangolo: lati o spigoli, vertici e facce. Non supporre tutte le misure uguali.',
'Rettangolo: 4 lati, lati opposti uguali, 4 vertici e angoli retti. Parallelepipedo rettangolo: 6 facce rettangolari, 12 spigoli, 8 vertici; le tre dimensioni possono differire.',
[('Separa piano e spazio','Sul tuo compito indica se osservi una figura piana o un solido.','Una scatola ha profondità; il disegno di una faccia è piano.'),('Conta per gruppi','Conta facce, spigoli e vertici in colonne diverse.','Sul cubo conta 4 spigoli sopra, 4 sotto e 4 verticali.'),('Formula una proprietà','Scrivi una frase che resti vera per tutta la figura.','Non dedurre misure dal solo disegno.')],
('Tabella di confronto','Affianca figura piana e solido con intestazioni diverse per lati e spigoli.','Impedisce di sommare elementi di tipi diversi.'),
['La dimensione è indicata','Facce, spigoli e vertici non sono confusi','Le proprietà non dipendono dalla prospettiva del disegno'],
('Un cubo ha 6 spigoli perché vedo 6 facce.','Faccia e spigolo sono elementi diversi.','Conta i segmenti di confine: 4 + 4 + 4 = 12.'),
'Usa una scatola vuota come modello; indica un tipo di elemento per volta e segna con etichette removibili quelli già contati.',
'Descrivi una figura del tuo libro con tre proprietà, senza affidarti alla sola apparenza.',category='trasversale')

r('M09-03','Convertire misure lineari, di area, volume, capacità e massa con unità coerenti.',
'Converti 2,5 m in cm; 3 m² in cm²; 2 dm³ in cm³ e in litri; 0,75 kg in g.',
['1 m = 100 cm, quindi 2,5 m = 250 cm. Per le aree il fattore è 100²: 3 m² = 30000 cm².','1 dm = 10 cm, quindi 1 dm³ = 1000 cm³: 2 dm³ = 2000 cm³. Poiché 1 dm³ = 1 L, sono 2 L.','1 kg = 1000 g: 0,75 kg = 750 g.'],
'250 cm; 30000 cm²; 2000 cm³ = 2 L; 750 g.',
'Converti 1,2 m in cm; 0,5 m² in cm²; 3 dm³ in cm³ e litri; 1,5 kg in g.',
'120 cm; 5000 cm²; 3000 cm³ = 3 L; 1500 g.',
[('Identifica la grandezza','Nel tuo esercizio segna lunghezza, area, volume, capacità o massa.','L’esponente ² o ³ cambia il fattore di conversione.'),('Scrivi l’equivalenza','Prima del calcolo scrivi quanto vale un’unità in quella richiesta.','Per m² → cm² il fattore è 10000, non 100.'),('Controlla la direzione','Verifica se il numero deve crescere passando a un’unità più piccola.','L’oggetto resta uguale: cambiano unità e numero.')],
('Conversione esplicita','Scrivi il fattore prima di moltiplicare, senza affidarti solo agli spostamenti della virgola.','Permette di distinguere lunghezze, aree e volumi.'),
['La grandezza è identificata','Il fattore considera l’esponente','L’unità finale è quella richiesta'],
('3 m² = 300 cm².','Hai usato il fattore delle lunghezze.','1 m² è un quadrato di 100 cm per 100 cm: 10000 cm².'),
'Usa una tabella separata per ogni grandezza con equivalenze di base visibili; non mescolare scale lineari e quadratiche.',
'Su una conversione assegnata scrivi prima l’equivalenza di un’unità.')

r('M09-04','Distinguere e calcolare perimetro, area, superficie totale e volume.',
'Un rettangolo ha lati 5 cm e 3 cm. Un parallelepipedo rettangolo ha dimensioni 5 cm, 3 cm e 2 cm. Calcola perimetro e area del rettangolo, superficie totale e volume del solido.',
['Rettangolo: P = 2(5 + 3) = 16 cm; A = 5 × 3 = 15 cm².','Solido: le coppie di facce hanno aree 15, 10 e 6 cm². S = 2(15 + 10 + 6) = 62 cm².','Volume: V = 5 × 3 × 2 = 30 cm³. Distinguo bordo, copertura e spazio occupato.'],
'P = 16 cm; A = 15 cm²; superficie totale = 62 cm²; volume = 30 cm³.',
'Un quadrato ha lato 4 cm e un cubo ha spigolo 4 cm. Calcola perimetro e area del quadrato, superficie totale e volume del cubo.',
'Quadrato: P = 16 cm, A = 16 cm². Cubo: S = 6 × 16 = 96 cm²; V = 4³ = 64 cm³.',
[('Nomina ciò che misuri','Accanto alla domanda scrivi bordo, regione piana, facce o spazio del solido.','Superficie totale comprende tutte le facce, anche quelle non visibili.'),('Scegli la formula','Scrivi la formula con lettere e poi sostituisci le misure.','La profondità 2 compare nel volume e nelle facce laterali.'),('Verifica le unità','Controlla cm per bordo, cm² per area e superficie, cm³ per volume.','Stesso numero con unità diversa non significa stessa grandezza.')],
('Confronto delle grandezze','Affianca quattro riquadri: P, A, S, V con disegno e unità.','Aiuta a scegliere la formula a partire dalla richiesta.'),
['La formula risponde alla grandezza richiesta','Sono considerate tutte le facce','Le unità distinguono lunghezza, area e volume'],
('Superficie del parallelepipedo = 5 × 3 × 2 = 30 cm².','Il prodotto delle tre dimensioni è volume.','Somma le aree delle sei facce: 62 cm².'),
'Usa quattro riquadri con etichette e unità già presenti; scegli tu i dati da inserire nel formulario.',
'Per il tuo esercizio evidenzia la parola della domanda prima di cercare la formula.')

r('M09-05','Applicare Pitagora e un rapporto di similitudine in situazioni distinte.',
'Un triangolo rettangolo ha cateti 6 cm e 8 cm. Calcola l’ipotenusa. Un triangolo simile con fattore di ingrandimento 2 quali lati ha?',
['Pitagora: c² = 6² + 8² = 36 + 64 = 100.','L’ipotenusa è c = √100 = 10 cm, maggiore di ogni cateto.','Nella figura simile moltiplico tutti i lati per 2: 12, 16, 20 cm. Gli angoli corrispondenti restano uguali.'],
'Ipotenusa 10 cm. Triangolo ingrandito: cateti 12 e 16 cm, ipotenusa 20 cm.',
'Un triangolo rettangolo ha cateti 5 e 12 cm. Trova l’ipotenusa e i lati di una riduzione con fattore 1/2.',
'c² = 25 + 144 = 169; c = 13 cm. Riduzione: 2,5 cm, 6 cm e 6,5 cm; rapporti dei lati tutti 1/2.',
[('Riconosci l’angolo retto','Nel tuo disegno segna il lato opposto all’angolo retto come ipotenusa.','Pitagora qui richiede un triangolo rettangolo.'),('Calcola quadrati e radice','Scrivi il quadrato dell’ipotenusa prima di estrarre la radice.','100 è c²; 10 è c.'),('Applica il fattore comune','Nella similitudine moltiplica ogni lato per lo stesso numero.','Raddoppiare solo un lato non produce una figura simile.')],
('Disegno etichettato','Segna cateti e ipotenusa, poi collega ciascun lato al suo corrispondente nella figura simile.','Previene lo scambio di dati e del fattore.'),
['L’ipotenusa è opposta all’angolo retto','La radice è estratta dal quadrato','Tutti i lati usano lo stesso fattore'],
('c = 6² + 8² = 100 cm.','Hai trovato il quadrato della lunghezza.','Calcola √100 = 10 cm.'),
'Usa un disegno con simbolo dell’angolo retto e tre etichette; conserva una riga distinta per c² e una per c.',
'Nel tuo problema segna prima l’ipotenusa; nella similitudine disegna le frecce del fattore.')

r('M09-06','Leggere coordinate e applicare traslazioni e simmetrie sul piano.',
'Segna A(1,2), B(3,2), C(1,4). Trasla ogni punto di 2 unità a destra e 1 in basso; poi trova il simmetrico di A rispetto all’asse y.',
['Leggo prima x, poi y: A è 1 a destra e 2 in alto dall’origine.','La traslazione è (x,y) → (x + 2,y − 1): A′(3,1), B′(5,1), C′(3,3).','Per la simmetria sull’asse y cambio il segno di x: A simmetrico è (−1,2).'],
'Punti traslati (3,1), (5,1), (3,3); simmetrico di A rispetto a y: (−1,2).',
'Segna P(−2,3) e Q(1,1). Trasla di 1 a destra e 2 in alto. Trova anche il simmetrico di P rispetto all’asse x.',
'P′(−1,5), Q′(2,3); simmetrico di P rispetto a x: (−2,−3).',
[('Leggi gli assi','Sul tuo piano indica origine e direzioni positive prima di segnare i punti.','La coppia è (x,y), non (y,x).'),('Scrivi la trasformazione','Indica che cosa cambia per x e per y.','Destra aumenta x; basso diminuisce y.'),('Controlla i punti','Confronta lo spostamento di tutti i punti e la distanza dall’asse nella simmetria.','Una traslazione usa lo stesso spostamento per tutti.')],
('Regola accanto al grafico','Scrivi (x + 2,y − 1) e completa una tabella prima di disegnare.','Distingue il calcolo delle coordinate dal posizionamento.'),
['Gli assi e la scala sono etichettati','La traslazione è uguale per tutti','La simmetria conserva la distanza dall’asse'],
('Il simmetrico di (1,2) sull’asse y è (1,−2).','Hai cambiato y: questa è la simmetria sull’asse x.','Cambia x: (−1,2).'),
'Usa un piano con assi evidenti e tabella x/y; traccia il percorso orizzontale prima di quello verticale.',
'Sul tuo esercizio separa tabella delle nuove coordinate e disegno.')

r('M09-07','Usare dati dichiarati e proprietà senza dedurre misure dall’apparenza.',
'La figura è descritta così: triangolo ABC isoscele con AB = AC, angolo A = 40°. Trova B e C; non è fornita una scala del disegno.',
['AB = AC indica che gli angoli alla base B e C sono uguali.','La somma degli angoli è 180°: B + C = 180° − 40° = 140°.','Divido in due parti uguali: B = C = 70°. Non deduco le lunghezze dalla figura.'],
'B = 70° e C = 70°; le lunghezze dei lati non sono determinabili dai dati.',
'Un triangolo DEF è isoscele con DE = DF e angolo D = 50°. Trova E e F. Puoi concludere che DE = 5 cm?',
'E = F = (180° − 50°)/2 = 65°. Non si può concludere DE = 5 cm senza un dato di lunghezza o scala.',
[('Raccogli i dati segnati','Copia solo misure, simboli di uguaglianza e proprietà esplicitamente date.','Una figura che sembra equilatera può non esserlo.'),('Collega una proprietà','Scrivi quale dato permette ogni deduzione.','AB = AC implica B = C.'),('Distingui il ricavabile','Rispondi alle domande possibili e indica ciò che manca.','Per una lunghezza serve un dato che fissi la scala.')],
('Dati-deduzioni','Dividi il foglio in “dato” e “dedotto”, collegandoli con una freccia.','Rende controllabile l’origine delle informazioni.'),
['Ogni deduzione ha un dato o proprietà','La somma degli angoli è verificata','Non compaiono misure inventate dal disegno'],
('AB sembra 4 cm, quindi AB = 4 cm.','Il disegno potrebbe non essere in scala.','Usa soltanto la lunghezza dichiarata; qui non è data.'),
'Affianca al disegno un elenco numerato dei dati; indica con il dito il simbolo a cui si riferisce ogni riga.',
'Per una figura assegnata separa almeno due dati da due deduzioni.',category='dislessia')

r('M09-08','Raccogliere dati categoriali e rappresentare frequenze in tabella e grafico.',
'In una classe immaginaria 8 risposte alla domanda “mezzo usato per arrivare a scuola” sono: piedi, bus, bici, piedi, bus, piedi, bici, piedi. Costruisci una tabella e un grafico a barre.',
['Definisco tre categorie e conto una risposta alla volta: piedi 4, bus 2, bici 2.','Controllo la somma: 4 + 2 + 2 = 8.','Disegno barre distinte con asse orizzontale “mezzo” e verticale “numero di risposte”, scala di una risposta per quadretto.'],
'Tabella: piedi 4; bus 2; bici 2. Barre di altezza 4, 2, 2; totale 8.',
'Sei preferenze immaginarie di frutta sono: mela, pera, mela, banana, pera, mela. Costruisci tabella e barre.',
'Mela 3, pera 2, banana 1; totale 6. Tre barre distinte alte 3, 2, 1, con categorie e scala esplicite.',
[('Definisci la domanda','Nel tuo compito scrivi che cosa conta ogni risposta e quali categorie usi.','Non raccogliere dati personali per esercitarti: usa quelli forniti.'),('Conta con tacche','Aggiungi una tacca per ogni risposta prima di scrivere le frequenze.','Spunta ogni voce già contata.'),('Rappresenta e controlla','Disegna barre con stessa scala e confronta il totale con l’elenco.','Il titolo dice a che cosa si riferiscono i dati.')],
('Tabella prima del grafico','Passa dall’elenco alle tacche, poi ai numeri, infine alle barre.','Fornisce una base controllabile al disegno.'),
['Ogni risposta è contata una volta','Le frequenze sommano al totale','Il grafico ha titolo, etichette e scala'],
('Disegno quattro barre per “piedi” e due per “bus”.','Una barra rappresenta la categoria, la sua altezza la frequenza.','Disegna una barra per piedi alta 4 e una per bus alta 2.'),
'Usa righe già etichettate e una spunta sull’elenco; per il grafico fornisci assi e scala ma lascia scegliere le altezze.',
'Trasforma un elenco di dati del tuo libro in tabella prima di disegnare il grafico.',category='trasversale')

r('M09-09','Calcolare frequenze, media, mediana e moda distinguendone il significato.',
'I dati sono 2, 3, 3, 4, 8. Calcola frequenze, media, mediana e moda.',
['I valori ordinati sono già 2, 3, 3, 4, 8; frequenze: 2→1, 3→2, 4→1, 8→1.','Somma 20 e divido per 5: media = 4.','La mediana è il terzo dato, 3; la moda è 3 perché compare due volte. Frequenza relativa di 3: 2/5 = 40%.'],
'Media 4, mediana 3, moda 3; frequenze assolute 1,2,1,1 e relative 20%,40%,20%,20%.',
'Analizza 1, 2, 2, 5. Calcola frequenze, media, mediana e moda.',
'Frequenze 1→1, 2→2, 5→1; relative 25%,50%,25%. Media 10/4 = 2,5; mediana (2 + 2)/2 = 2; moda 2.',
[('Ordina e conta','Nel tuo elenco metti i valori in ordine conservando le ripetizioni.','Due 3 sono due osservazioni, non una.'),('Calcola gli indici','Per media usa somma/numero; per mediana trova il centro; per moda conta le ripetizioni.','Con un numero pari di dati la mediana è la media dei due centrali.'),('Spiega le differenze','Scrivi che cosa descrive ogni indice e verifica il totale delle frequenze.','Il valore alto 8 sposta la media senza diventare la moda.')],
('Tre domande distinte','Affianca “quanto in media?”, “quale centro?”, “quale più frequente?” ai calcoli.','Evita di usare un’unica procedura per indici diversi.'),
['Le ripetizioni restano nell’elenco','La media divide per il numero di dati','Mediana e moda usano criteri diversi'],
('La media è (2 + 3 + 4 + 8)/4 perché 3 si ripete.','La media deve includere ogni osservazione.','Somma anche il secondo 3 e dividi per 5.'),
'Usa un riquadro per ogni indice e una striscia ordinata dei dati; copri gli altri riquadri mentre calcoli.',
'Sui dati assegnati conserva l’elenco ordinato accanto ai tre indici.')

r('M09-10','Calcolare una probabilità semplice specificando esiti e ipotesi.',
'Un sacchetto contiene 3 palline rosse e 2 blu, identiche per forma e peso. Mescoli ed estrai una pallina senza guardare. Qual è la probabilità di rosso?',
['Gli esiti elementari sono le 5 singole palline; si assume che ciascuna abbia la stessa possibilità di essere estratta.','Tre palline soddisfano l’evento rosso: casi favorevoli 3 su 5.','P(rosso) = 3/5 = 0,6 = 60%; P(blu) = 2/5 = 40%.'],
'Probabilità di rosso 3/5, cioè 60%. Non significa che ogni cinque estrazioni appariranno esattamente tre rossi.',
'Un dado regolare a sei facce è lanciato una volta. Calcola la probabilità di un numero maggiore di 4 e di un numero pari.',
'Maggiore di 4: {5,6}, quindi 2/6 = 1/3. Pari: {2,4,6}, quindi 3/6 = 1/2. Si assume dado equilibrato.',
[('Elenca gli esiti','Per il tuo esperimento scrivi i singoli esiti possibili e l’ipotesi di uguale possibilità.','Non contare soltanto i colori: le palline sono cinque.'),('Definisci l’evento','Segna gli esiti che rispettano esattamente la richiesta.','“Maggiore di 4” non comprende 4.'),('Calcola il rapporto','Dividi favorevoli per possibili e controlla che il valore sia tra 0 e 1.','Una probabilità non è una promessa sul prossimo esito.')],
('Spazio degli esiti','Disegna tutte le palline o scrivi tutti i numeri del dado, poi cerchia i favorevoli.','Rende visibile il denominatore.'),
['Gli esiti elementari sono distinti','L’evento segue la consegna','La probabilità è tra 0 e 1'],
('P(rosso) = 1/2 perché ci sono due colori.','I colori non hanno lo stesso numero di palline.','Conta le palline: 3 favorevoli su 5.'),
'Rappresenta ciascun esito con una casella separata; evidenzia i favorevoli senza cancellare gli altri.',
'Su un problema di probabilità scrivi prima tutti gli esiti e soltanto dopo la frazione.')

r('M10-01','Spiegare un fenomeno collegando condizioni, processo ed effetto.',
'Testo: “L’acqua liquida può passare a vapore dalla sua superficie anche senza bollire. Questo processo è chiamato evaporazione. Con aria più calda o in movimento l’evaporazione può aumentare, a parità delle altre condizioni.” Spiega perché due panni uguali possono asciugarsi a velocità diverse.',
['Identifico il cambiamento: acqua liquida → vapore nell’aria.','Collego le condizioni: aria più calda o in movimento può favorire l’evaporazione.','Formulo una spiegazione prudente: se i panni hanno uguale acqua iniziale e materiale, condizioni diverse dell’aria possono cambiare il tempo di asciugatura.'],
'I panni si asciugano perché l’acqua evapora; aria più calda o in movimento può accelerare il processo. Non serve raggiungere l’ebollizione.',
'Testo: “Il vapore d’acqua nell’aria può condensare quando incontra una superficie abbastanza fredda.” Spiega le goccioline esterne a un bicchiere freddo chiuso, senza perdite.',
'Il vapore presente nell’aria condensa sulla superficie fredda e forma gocce liquide. Non è necessario che l’acqua attraversi il vetro; bicchiere chiuso e senza perdite escludono quella spiegazione nel compito.',
[('Trova il cambiamento','Nel tuo testo identifica che cosa cambia e tra quali stati.','Evaporazione: liquido a gas; condensazione: gas a liquido.'),('Collega le condizioni','Sottolinea le condizioni che possono influire e ciò che deve restare uguale.','“Può aumentare” non significa “aumenta sempre”.'),('Spiega con una catena','Scrivi condizione → processo → effetto osservabile.','Usa i dati del testo, senza aggiungere una causa non fornita.')],
('Spiegazione causale','Costruisci una frase “quando… il processo… quindi…” usando stato e condizioni del testo.','Organizza la spiegazione oltre la semplice definizione.'),
['Il cambiamento di stato è corretto','La causa è collegata ai dati','Le conclusioni rispettano le condizioni indicate'],
('L’acqua evapora solo se bolle.','Il testo dice che può evaporare dalla superficie anche senza bollire.','Distingui evaporazione ed ebollizione; usa l’esempio dei panni.'),
'Dividi il testo in tre righe: stato iniziale, processo, condizioni; puoi ascoltare la lettura e costruire la catena a voce.',
'Per il fenomeno assegnato scrivi una catena di tre elementi e cerca nel testo ciascun collegamento.')

r('M10-02','Descrivere osservazioni senza mescolarle a interpretazioni.',
'Dati di osservazione di una piantina in immagine: fusto verde alto 8 cm; quattro foglie; due foglie inclinate verso una finestra a destra. Scrivi tre osservazioni e separa una possibile spiegazione.',
['Registro misure e conteggi: fusto alto 8 cm; quattro foglie.','Descrivo la posizione: due foglie sono inclinate verso la finestra a destra.','Separo l’ipotesi: la luce potrebbe influire sull’orientamento; questi soli dati non provano la causa.'],
'Osservazioni: altezza 8 cm, quattro foglie, due inclinate a destra. Ipotesi distinta: possibile relazione con la luce.',
'Una pietra osservata è grigia, lunga 4 cm, ha superficie ruvida e tre macchie bianche. Scrivi tre osservazioni. La frase “viene da un vulcano” è osservazione o ipotesi?',
'Sono osservazioni colore grigio, lunghezza 4 cm, superficie ruvida, tre macchie bianche. “Viene da un vulcano” è un’ipotesi sull’origine, non ricavabile con certezza da questi dati.',
[('Scegli ciò che osservi','Per il tuo oggetto indica colore, forma, misura o numero realmente disponibili.','“Bello” è un giudizio, non una misura.'),('Descrivi in modo preciso','Usa una frase per caratteristica e indica l’unità per le misure.','“Alto 8 cm” è più controllabile di “abbastanza alto”.'),('Separa l’ipotesi','Scrivi le spiegazioni in una colonna diversa.','Puoi usare “potrebbe”, poi dire quali dati servirebbero.')],
('Doppia colonna osservazione-ipotesi','Trascrivi prima i dati visibili e solo dopo le possibili spiegazioni.','Evita di presentare un’interpretazione come fatto osservato.'),
['Le osservazioni sono verificabili nei dati','Le misure hanno unità','L’ipotesi è etichettata separatamente'],
('Osservo che la pianta vuole la luce.','“Vuole” attribuisce un’intenzione che non è osservabile qui.','Descrivi l’inclinazione e formula una possibile influenza della luce.'),
'Usa una lista con icone testuali “colore, numero, misura, posizione”; registra anche con parole brevi o dettatura.',
'Descrivi un’immagine del tuo libro con tre dati e una eventuale ipotesi separata.')

r('M10-03','Classificare elementi con un criterio esplicito e confrontarne proprietà.',
'Dati: ferro e rame conducono bene elettricità; plastica e legno asciutto la conducono molto meno nelle condizioni descritte. Classifica i quattro materiali e confronta ferro e plastica. Non eseguire prove con prese o corrente di rete.',
['Scelgo il criterio “conduzione elettrica nelle condizioni descritte”.','Gruppo dei buoni conduttori: ferro e rame. Gruppo di materiali isolanti nell’uso considerato: plastica e legno asciutto.','Confronto ferro e plastica sullo stesso criterio: il ferro conduce bene, la plastica molto meno. Non classifico per colore.'],
'Ferro/rame: buoni conduttori; plastica/legno asciutto: isolanti nelle condizioni indicate. Il criterio resta la conduzione.',
'Dati: vetro e plastica trasparente lasciano passare luce; cartone e legno sono opachi. Classifica e confronta vetro e cartone.',
'Criterio: passaggio della luce. Trasparenti: vetro e plastica trasparente; opachi: cartone e legno. Il vetro permette di vedere attraverso, il cartone no nei dati forniti.',
[('Dichiara il criterio','Sul tuo compito scrivi la proprietà usata per formare i gruppi.','Non cambiare da conduzione a durezza a metà classificazione.'),('Applica a tutti','Per ogni elemento usa il dato relativo a quella proprietà.','Mantieni qualifiche come “asciutto” o “trasparente”.'),('Confronta due elementi','Scrivi una somiglianza o differenza rispetto allo stesso criterio.','Un materiale può cambiare gruppo se cambia il criterio.')],
('Matrice di proprietà','Metti gli elementi in righe e il criterio nella colonna da compilare.','Rende coerente la classificazione di tutti gli elementi.'),
['Il criterio è esplicito','Ogni elemento compare una volta','Le condizioni del testo sono conservate'],
('Il legno è sempre isolante in ogni condizione.','Il dato riguarda legno asciutto nelle condizioni descritte.','Mantieni la condizione e non generalizzare oltre i dati.'),
'Usa una tabella con quattro righe già etichettate; ascolta un dato alla volta e indica il gruppo corrispondente.',
'Sulla tua classificazione scrivi il criterio sopra la tabella e controlla tutte le righe.')

r('M10-04','Interpretare uno schema, un modello e un’immagine riconoscendone i limiti.',
'Schema fornito: Sole → energia luminosa → pianta. Modello: radici assorbono acqua; foglie ricevono luce e scambiano gas. Immagine descritta: frecce blu dal terreno alle radici, frecce gialle dal Sole alle foglie. Spiega simboli e limiti.',
['Leggo la legenda: blu indica acqua; giallo luce. Le frecce mostrano direzione, non la forma reale delle sostanze.','Collego schema e modello: luce arriva alle foglie, acqua è assorbita dalle radici; non sono la stessa cosa.','Indico un limite: il modello non mostra tutti i passaggi della fotosintesi e non dà quantità o tempi.'],
'Lo schema rappresenta flussi di acqua ed energia luminosa verso la pianta; colori e frecce sono convenzioni. Non è una fotografia completa del processo.',
'Schema: acqua liquida → evaporazione → vapore → condensazione → gocce. Immagine descritta: freccia rossa verso “vapore”, blu verso “gocce”. Spiega il modello e indica due dati che non fornisce.',
'Rappresenta due cambiamenti di stato opposti. I colori distinguono passaggi e richiedono una legenda, non sono colori del vapore. Mancano quantità, temperature precise e tempi; basta indicarne due.',
[('Leggi la legenda','Nel tuo schema identifica significato di colori, frecce e simboli.','Se la legenda manca, non inventare ciò che significa un colore.'),('Traduci in frasi','Scrivi una frase per ogni relazione disegnata.','“Radici assorbono acqua” è più preciso di “la pianta prende cose”.'),('Dichiara il limite','Indica che cosa è semplificato o non rappresentato.','Un modello serve a capire alcuni aspetti, non tutti.')],
('Traduzione visivo-verbale','Trasforma ogni freccia in una frase con origine, relazione e destinazione.','Fa controllare il significato del disegno.'),
['Ogni simbolo è interpretato dalla legenda','Le relazioni sono espresse in parole','È indicato almeno un limite del modello'],
('Le frecce gialle sono tubi che entrano nelle foglie.','La freccia è un simbolo della direzione della luce.','Scrivi “energia luminosa arriva alle foglie”.'),
'Aggiungi etichette scritte ai colori e numera le frecce; analizza una relazione per volta.',
'Per una figura del tuo testo scrivi due relazioni e un limite della rappresentazione.')

r('M10-05','Distinguere domanda, ipotesi e previsione verificabile.',
'Situazione: due fogli identici, uno piano e uno piegato a fisarmonica, sostengono piccoli pesi tra due supporti. Formula domanda, ipotesi e previsione senza aver ancora raccolto risultati.',
['Domanda: la piegatura cambia quanti pesi uguali il foglio sostiene?','Ipotesi: la forma piegata potrebbe rendere il foglio più resistente al piegamento in questa disposizione.','Previsione: se l’ipotesi è adeguata, a parità di foglio, distanza dei supporti e pesi, il foglio piegato sosterrà più pesi di quello piano.'],
'La domanda chiede che cosa confrontare; l’ipotesi propone una spiegazione; la previsione indica il risultato atteso e le condizioni.',
'Due cubetti di ghiaccio uguali sono posti su superfici dello stesso materiale, una in stanza più calda e una più fresca. Formula domanda, ipotesi e previsione; non eseguire prove senza autorizzazione.',
'Domanda: la temperatura ambiente cambia il tempo di fusione? Ipotesi: aria più calda può favorire lo scambio di energia verso il ghiaccio. Previsione: con cubetti e superfici uguali, il cubetto nella stanza più calda dovrebbe fondere prima. È un’attesa, non un risultato già osservato.',
[('Formula la domanda','Nel tuo compito indica due condizioni da confrontare e una grandezza da osservare.','“Cosa succede?” è troppo ampio: chiedi quanti pesi o quanto tempo.'),('Proponi una spiegazione','Scrivi “potrebbe… perché…” senza trattarla come dato.','Non dire “ho dimostrato” prima della prova.'),('Prevedi un esito','Usa “se… allora…” e indica ciò che deve restare uguale.','Una previsione deve poter essere confrontata con misure.')],
('Struttura domanda-ipotesi-previsione','Scrivi tre riquadri separati e collega la previsione alla spiegazione.','Distingue il problema di ricerca dall’esito atteso.'),
['La domanda identifica un confronto','L’ipotesi è una spiegazione provvisoria','La previsione riguarda un dato misurabile'],
('La previsione è “il foglio è bello”.','Non corrisponde al confronto né a una misura di resistenza.','Prevedi quale foglio sosterrà più pesi, con condizioni uguali.'),
'Usa tre inizi di frase già scritti: “Cambia…?”, “Potrebbe… perché…”, “Se… allora…”; scegli tu i contenuti.',
'Per la tua attività scientifica scrivi prima la previsione e non modificarla dopo per farla coincidere con i dati.',category='trasversale')

r('M10-06','Progettare un confronto controllato e leggere risultati senza generalizzare.',
'Prova su carta: due fogli identici tra supporti distanti 10 cm; A piano e B piegato a fisarmonica. Si aggiungono pesi identici uno alla volta al centro fino al cedimento. Risultati in tre prove: A 2,2,3 pesi; B 5,6,5. Identifica variabile, controlli e conclusione.',
['Variabile cambiata: forma del foglio. Misura: numero di pesi sostenuti prima del cedimento.','Tengo uguali tipo di foglio, distanza 10 cm, tipo di pesi, posizione e modo di aggiungerli.','In queste prove B sostiene più pesi di A; ripetizioni mostrano piccole differenze. Non dimostra ogni possibile forma o materiale.'],
'Il confronto sostiene che, in questa disposizione, la piegatura scelta aumenta il numero di pesi sostenuti.',
'Prova su carta: due rampe identiche lunghe 30 cm, altezza A 5 cm e B 10 cm; stessa pallina lasciata senza spinta. Tempi in secondi: A 1,8;1,9;1,8 e B 1,2;1,3;1,2. Indica variabile, misura, controlli e conclusione.',
'Variabile: altezza. Misura: tempo per percorrere la rampa. Controlli: pallina, lunghezza/materiale, punto di rilascio e assenza di spinta. In queste prove la rampa più alta dà tempi minori; non si conclude “il doppio dell’altezza dimezza sempre il tempo”.',
[('Seleziona una variabile','Nel tuo protocollo scrivi che cosa cambia e che cosa misuri.','Piegatura e numero di pesi hanno ruoli diversi.'),('Fissa i controlli','Elenca condizioni uguali e ripetizioni previste.','Cambiare contemporaneamente foglio e distanza impedisce un confronto chiaro.'),('Concludi sui dati','Confronta le ripetizioni e formula una conclusione limitata al test.','Se i risultati si sovrappongono molto, segnala l’incertezza.')],
('Confronto controllato','Compila le colonne “cambio”, “misuro”, “mantengo” prima di osservare i risultati.','Rende interpretabile la differenza tra condizioni.'),
['Una sola variabile prevista cambia','Misura e procedura sono definite','La conclusione non supera le condizioni provate'],
('Cambio sia piegatura sia tipo di foglio e attribuisco la differenza alla piegatura.','Non separi l’effetto delle due modifiche.','Usa lo stesso tipo di foglio e cambia solo la forma.'),
'Usa tre colonne già etichettate e una lista numerata del protocollo; spunta ogni controllo mentre lo descrivi.',
'Sul tuo esperimento scolastico identifica prima una variabile, una misura e tre controlli.',category='trasversale')

r('M10-07','Registrare misure con unità e costruire una rappresentazione leggibile.',
'Un campione viene misurato ogni minuto. Tempo (min): 0,1,2,3. Temperatura (°C): 20,24,28,30. Crea tabella e grafico con tempo orizzontale e temperatura verticale.',
['Scrivo intestazioni “tempo (min)” e “temperatura (°C)” e associo 0→20, 1→24, 2→28, 3→30.','Scelgo scala orizzontale di 1 minuto e verticale di 2 °C, indicando se l’asse parte da 20. Segno (0,20),(1,24),(2,28),(3,30).','Leggo: in tre minuti la temperatura aumenta di 10 °C; gli incrementi sono 4,4,2 °C. Una linea può guidare la lettura, senza inventare nuove misure.'],
'Tabella di quattro coppie; grafico con punti corretti e unità. Aumento totale 10 °C; l’aumento per minuto non è sempre uguale.',
'Tempo (min): 0,2,4. Altezza dell’acqua (cm): 1,3,4. Rappresenta i dati e descrivi la variazione totale.',
'Punti (0,1),(2,3),(4,4), assi con min e cm. Aumento totale 3 cm; primo intervallo +2 cm, secondo +1 cm. Non sono incrementi costanti.',
[('Associa dato e unità','Nel tuo quaderno trascrivi ogni coppia senza cambiare ordine.','Un numero privo di unità non dice che cosa è misurato.'),('Scegli una scala','Disegna assi con tacche regolari e valori leggibili.','Dichiara l’origine scelta: non far sembrare 20 °C lo zero.'),('Leggi la variazione','Confronta primo e ultimo valore e poi gli intervalli.','Una curva regolare disegnata non sostituisce misure mancanti.')],
('Doppia rappresentazione dei dati','Passa dalla tabella ai punti e ricontrolla ogni punto nella tabella.','Permette di vedere l’andamento senza perdere le misure.'),
['Ogni punto corrisponde a una coppia','Gli assi hanno unità e scala regolare','La descrizione usa variazioni realmente presenti'],
('Scrivo 30 − 20 = 10 minuti.','La differenza riguarda temperature.','Scrivi 10 °C; i tempi si leggono sull’altro asse.'),
'Fornisci assi con unità e tacche già tracciate; lascia al ragazzo il posizionamento e la lettura delle coppie.',
'Per la tua tabella verifica ogni punto del grafico contro una riga.',category='discalculia')

r('M10-08','Scrivere una relazione separando scopo, metodo, risultati e conclusione.',
'Dati di laboratorio simulato: confronto carta piana/piegata; fogli identici; supporti a 10 cm; pesi uguali centrali. Tre prove: piano 2,2,3; piegato 5,6,5. Scrivi una breve relazione senza fingere di aver eseguito la prova.',
['Scopo: confrontare la resistenza delle due forme. Metodo: stessi fogli e pesi, stessa distanza, aggiunta di un peso per volta; tre prove.','Risultati: riporto in tabella piano 2,2,3 e piegato 5,6,5; sono dati forniti, non misure personali.','Conclusione: il foglio piegato sostiene più pesi nelle condizioni indicate. Limite: poche prove e un solo tipo di carta.'],
'Relazione esemplificativa: “Analizzo dati forniti. Con fogli e condizioni uguali, il piano sostiene 2,2,3 pesi e il piegato 5,6,5. I dati sostengono il vantaggio della piegatura usata; non descrivono ogni carta o forma.”',
'Dati simulati: due superfici A liscia e B ruvida; stessa pallina, stessa spinta prevista, tre distanze (cm): A 40,42,41; B 20,22,21. Scrivi scopo, metodo, risultati, conclusione e un limite.',
'Scopo: confrontare le distanze su due superfici. Metodo: stessa pallina e condizioni di spinta previste, tre prove. Risultati: le sei distanze in tabella con cm. Conclusione: qui la pallina percorre meno su B. Limite: controllare realmente che la spinta sia uguale; i dati forniti non bastano a verificarlo.',
[('Organizza le sezioni','Nel tuo compito usa scopo, materiali/metodo, risultati, conclusione e limiti.','Non mettere la conclusione prima di mostrare i risultati.'),('Riporta i dati','Usa una tabella con condizioni, ripetizioni e unità.','Dichiara se i dati sono raccolti da te o forniti.'),('Collega la conclusione','Cita una differenza dei risultati e un limite del metodo.','Non inventare osservazioni per completare la relazione.')],
('Struttura della relazione','Inserisci ciascuna frase nella sezione corretta e collega conclusione e tabella.','Rende verificabile che cosa hai fatto e che cosa sostieni.'),
['Il metodo permetterebbe di ripetere la prova','I risultati sono distinti dalla conclusione','Origine dei dati e limite sono espliciti'],
('Scrivo “ho misurato” anche se i dati sono nel testo.','Attribuisci a te un’osservazione non eseguita.','Scrivi “nei dati forniti risulta…” e riporta la tabella.'),
'Usa cinque intestazioni già pronte e una casella per ogni dato; puoi dettare la conclusione prima di trascriverla.',
'Nella tua relazione controlla che ogni conclusione abbia un riferimento alla tabella.',category='trasversale')

r('M10-09','Distinguere dato osservato e spiegazione da mettere alla prova.',
'Dati: una bustina di tè immersa in acqua colora l’acqua prima vicino alla bustina e poi più lontano. Proposta: sostanze del tè passano nell’acqua e si distribuiscono. Separa osservazioni e spiegazione; indica un limite.',
['Osservazioni fornite: il colore compare vicino alla bustina e successivamente più lontano.','Spiegazione proposta: alcune sostanze passano dalla bustina all’acqua e si distribuiscono; è diversa dalla descrizione del colore.','Il solo colore non misura la quantità di sostanze né distingue tutti i processi di trasporto; servirebbero dati ulteriori.'],
'Descrizione e spiegazione sono separate. L’osservazione è compatibile con la proposta ma non verifica ogni suo dettaglio.',
'Dati: una pozzanghera è più piccola dopo due ore di sole, senza pioggia. Proposta: parte dell’acqua è evaporata. Che cosa è osservato? Quali altre possibilità o dati consideri?',
'Osservato: diminuzione dell’estensione dopo due ore. Evaporazione è una spiegazione possibile; assorbimento nel terreno o scorrimento possono contribuire. Servono informazioni su superficie, profondità e perdite per attribuire tutto all’evaporazione.',
[('Scrivi i dati','Nel tuo fenomeno elenca ciò che si vede o misura senza “perché”.','“Il colore si estende” è una descrizione.'),('Proponi il meccanismo','Spiega come potrebbe prodursi il cambiamento.','Usa “compatibile con” quando i dati non isolano la causa.'),('Cerca un’alternativa','Indica un’altra spiegazione o un dato necessario per distinguerla.','Una sequenza temporale da sola non prova una causa.')],
('Confronto di spiegazioni','Affianca la spiegazione proposta a un’alternativa o limite e cerca il dato che le distinguerebbe.','Allena una conclusione proporzionata alle osservazioni.'),
['Il dato non contiene una causa inventata','La spiegazione indica un meccanismo','Il limite o l’alternativa è pertinente'],
('La pozzanghera è diminuita, quindi so che tutta l’acqua è evaporata.','Mancano dati che escludano altre perdite.','Distingui diminuzione osservata ed evaporazione possibile.'),
'Usa due colori o etichette scritte “vedo” e “spiego”; completa un dato alla volta senza dover rileggere tutto.',
'Nel tuo testo scientifico segna una frase di osservazione e una di spiegazione.')

r('M10-10','Risolvere un problema quantitativo con grandezze e unità coerenti.',
'Un campione ha massa 120 g e volume 40 cm³. Calcola densità media usando d = m/V. Un oggetto percorre 150 m in 30 s: calcola velocità media usando v = s/t.',
['Densità: identifico m = 120 g e V = 40 cm³; d = 120/40 = 3 g/cm³.','Velocità media: s = 150 m, t = 30 s; v = 150/30 = 5 m/s.','Controllo ricostruendo i dati: 3 × 40 = 120 g e 5 × 30 = 150 m. La velocità è media, non necessariamente costante.'],
'Densità media 3 g/cm³; velocità media 5 m/s.',
'Un campione ha massa 90 g e volume 30 cm³. Un oggetto percorre 240 m in 60 s. Calcola densità e velocità medie e verifica.',
'd = 90/30 = 3 g/cm³; v = 240/60 = 4 m/s. Controlli: 3 × 30 = 90 g; 4 × 60 = 240 m.',
[('Etichetta le grandezze','Nel tuo problema scrivi simbolo, dato e unità prima della formula.','Volume non è una lunghezza: qui è in cm³.'),('Sostituisci nella formula','Usa unità coerenti e conserva l’ordine del rapporto.','m/V non è V/m.'),('Ricostruisci un dato','Moltiplica il risultato per il denominatore e interpreta la media.','Una velocità media non descrive ogni istante.')],
('Formula con significato','Accanto a d scrivi “massa per unità di volume” e a v “spazio per unità di tempo”.','Aiuta a ricordare ordine e unità del rapporto.'),
['I dati hanno simboli e unità','Il rapporto ha l’ordine corretto','La verifica ricostruisce il dato iniziale'],
('Densità = 40/120 = 1/3 cm³/g.','Hai invertito la formula e ottenuto un’altra grandezza.','Usa massa/volume: 120/40 = 3 g/cm³.'),
'Usa una scheda dati-formula-sostituzione-unità; lascia calcolatrice e formulario disponibili per concentrarti sul significato.',
'Per il tuo problema quantitativo conserva dati e verifica nella stessa pagina.',category='discalculia')

r('M10-11','Collegare un principio scientifico a una scelta di salute o ambiente senza conclusioni eccessive.',
'Dati didattici: una borraccia riutilizzabile evita bottiglie monouso quando è usata molte volte; va pulita secondo le istruzioni. Un rubinetto aperto durante la spazzolatura consuma più acqua che chiuderlo mentre non serve. Collega scelta, meccanismo e limite.',
['Borraccia: riuso → minore richiesta di bottiglie monouso per quelle bevande; considero pulizia e durata.','Rubinetto: chiusura quando non serve → minore tempo di flusso → meno acqua consumata a parità di portata.','Non concludo che qualsiasi borraccia abbia sempre impatto zero; produzione, uso e pulizia hanno effetti.'],
'Due collegamenti motivati: riuso riduce monouso; ridurre il tempo del rubinetto riduce il consumo. Pulizia resta necessaria secondo le istruzioni del prodotto.',
'Dati: lavare le mani secondo le indicazioni scolastiche aiuta a ridurre la trasmissione di alcuni microrganismi; spegnere una luce inutilizzata riduce il suo consumo elettrico. Spiega un collegamento per salute e uno per ambiente, con un limite.',
'Salute: lavaggio → rimozione di parte dei microrganismi → riduzione del rischio di alcune trasmissioni, senza garantire assenza di malattia. Ambiente: spegnimento → minore tempo acceso → minor consumo di quella luce; il risparmio totale dipende anche da potenza e durata.',
[('Identifica il principio','Nel testo scolastico trova il meccanismo: riuso, rimozione, flusso o consumo.','Non basta scrivere “fa bene”.'),('Collega una scelta','Indica un comportamento concreto e come cambia il processo.','Chiudere il rubinetto cambia il tempo di flusso.'),('Mantieni il limite','Scrivi una condizione o ciò che la scelta non garantisce.','Un esempio di salute non è una diagnosi o consiglio individuale.')],
('Catena scelta-effetto','Scrivi scelta → processo → effetto e aggiungi una condizione.','Trasforma uno slogan in una spiegazione controllabile.'),
['Il collegamento cita un meccanismo','La scelta è concreta','Sono evitati “sempre”, “zero impatto” o garanzie assolute'],
('Lavare le mani impedisce ogni malattia.','La prevenzione riduce alcuni rischi senza azzerarli tutti.','Scrivi “aiuta a ridurre la trasmissione di alcuni microrganismi”.'),
'Usa una catena con tre caselle e una quarta “limite”; leggi il testo in brevi parti senza chiedere dati sanitari personali.',
'Per un argomento di salute o ambiente del tuo libro scrivi un collegamento motivato e un limite.')

r('M11-01','Ricavare chi, quando e dove da un breve ascolto in inglese.',
'Fai leggere due volte, senza vedere il testo durante l’ascolto: “Hi, I’m Ben. On Friday I go to the library at four. I meet my friend Amy there.” Domande: chi parla? Quale giorno? Dove e a che ora? Chi incontra?',
['Prima lettura: riconosco il tema, un incontro in biblioteca.','Seconda lettura: annoto Ben, Friday, library, four, Amy nei cinque spazi delle domande.','Dopo l’ascolto confronto con il copione: “at four” indica le quattro, non quattro amici.'],
'Ben; Friday; at the library; at four; Amy.',
'Copione da far leggere due volte: “Hello, I’m Mia. On Tuesday I play tennis in the park at five. I play with Leo.” Chi? Giorno? Attività? Luogo? Ora? Con chi?',
'Mia; Tuesday; tennis; in the park; at five; Leo. Chi ascolta non deve avere il copione visibile. Se lo legge da solo, la prova riguarda comprensione scritta.',
[('Prepara le domande','Sul tuo ascolto scrivi chi, quando, dove e attività prima di iniziare.','Non cercare ogni parola al primo ascolto.'),('Ascolta in due giri','Nel primo identifica il tema; nel secondo completa i dati.','Lascia un trattino dove non hai colto l’informazione.'),('Verifica i punti incerti','Chiedi una ripetizione mirata e confronta con il testo solo dopo.','Non trasformare una parola non sentita in una risposta inventata.')],
('Ascolto orientato','Prepara cinque caselle e cerca le parole che rispondono a quelle domande.','Riduce il numero di informazioni da inseguire insieme.'),
['Il copione non è visibile durante l’ascolto','Le risposte riguardano i dati ascoltati','Le incertezze sono segnate prima del confronto'],
('Rispondo Monday perché è il giorno che conosco meglio.','La parola deve provenire dall’ascolto, non dalla familiarità.','Lascia la casella incerta e riascolta il tratto sul giorno.'),
'Concorda una lettura chiara con pause fra le frasi e una tabella di domande; evita di mostrare in anticipo le risposte.',
'Usa un breve ascolto del corso con quattro caselle; senza lettore disponibile ripassa il lessico, ma non chiamarlo prova orale.',category='trasversale',difficulty='Perdo le informazioni mentre ascolto')

r('M11-02','Comprendere un testo inglese usando indizi e informazioni esplicite.',
'Leggi: “Sara lives near a small park. Every Saturday she rides her bike there with her brother. They take water but they do not take food.” Dove vive? Quando va al parco? Con chi? Che cosa portano e non portano?',
['Cerco “lives near”: Sara abita vicino a un piccolo parco.','Collego “Every Saturday” all’attività e “with her brother” alla persona.','La negazione “do not” riguarda food: portano acqua, non cibo.'],
'Near a small park; every Saturday; with her brother; they take water, but they do not take food.',
'Leggi: “Tom visits his aunt on Sundays. She has two cats. Tom brings a book, but he does not bring his phone.” Quando visita la zia? Quanti gatti ha lei? Che cosa porta e non porta Tom?',
'On Sundays; two cats; a book, not his phone. “She” indica la zia.',
[('Leggi la domanda','Nel tuo testo sottolinea le parole della domanda che indicano il dato da cercare.','“When?” chiede il tempo, “Who with?” una persona.'),('Trova la frase prova','Accanto a ogni risposta copia poche parole del testo che la sostengono.','Non basta una risposta plausibile sulla vita di Sara.'),('Controlla pronomi e no','Verifica a chi si riferiscono he/she/they e quale parte è negata.','“They do not take food” non nega l’acqua.')],
('Lettura con evidenza','Abbina ogni risposta a un frammento preciso del testo.','Tiene la comprensione ancorata alle informazioni disponibili.'),
['Ogni risposta ha una frase di supporto','I pronomi hanno un referente corretto','La negazione è conservata'],
('They take food perché ho visto la parola food.','La negazione cambia la frase.','Leggi tutto il gruppo “do not take food”.'),
'Fornisci il testo in righe brevi con spazio fra le frasi; usa un segnariga o lettura audio mantenendo visibili le domande.',
'Su un breve testo del corso segna il frammento che giustifica ogni risposta.')

r('M11-03','Scambiare informazioni in una conversazione breve e chiedere chiarimenti.',
'Con un compagno rappresenta: A vuole sapere quale sport piace a B e in quale giorno lo pratica. B ama tennis e gioca il sabato. A non sente il giorno e chiede di ripeterlo.',
['A apre con “What sport do you like?”; B risponde “I like tennis.”','A chiede “When do you play?”; B risponde “On Saturdays.”','A chiede “Sorry, can you repeat that?”; B ripete “On Saturdays.”; A chiude “Thanks!”'],
'Dialogo: “What sport do you like?” “I like tennis.” “When do you play?” “On Saturdays.” “Sorry, can you repeat that?” “On Saturdays.” “Thanks!”',
'A chiede a B quale cibo piace e dove lo mangia. B ama pizza e la mangia a casa. A chiede di ripetere il luogo. Scrivi e prova il dialogo.',
'Una soluzione: “What food do you like?” “I like pizza.” “Where do you eat it?” “At home.” “Can you repeat that, please?” “At home.” “Thank you.” Controlla scambio di turni e riparazione dell’incomprensione.',
[('Prepara due intenzioni','Per il tuo dialogo scrivi che cosa vuoi chiedere e che cosa devi rispondere.','Non preparare solo un monologo.'),('Scambia un turno','Ascolta la domanda e rispondi al dato richiesto prima di continuare.','What sport? non richiede subito il giorno.'),('Ripara l’incomprensione','Usa una frase per chiedere ripetizione e riprendi lo scambio.','Non fingere di capire: “Can you repeat that?” è parte del compito.')],
('Prova a ruoli','Alterna A e B usando prima una carta con intenzioni e poi una sola parola per turno.','Allena domanda, risposta e adattamento al compagno.'),
['Le risposte seguono la domanda','Entrambi hanno turni','Compare una richiesta di chiarimento pertinente'],
('A chiede Where? e B risponde On Saturdays.','La domanda chiede un luogo, non un giorno.','Rispondi con il luogo e riserva il giorno a When?.'),
'Usa carte con “chiedi sport”, “rispondi”, “chiedi giorno”, “ripeti”; concedi qualche secondo di preparazione.',
'Prova il tuo dialogo cambiando un solo dato e alternando i ruoli.',category='trasversale',difficulty='Dimentico che cosa devo chiedere quando arriva il mio turno')

r('M11-04','Organizzare una presentazione e un breve racconto orale con un ordine chiaro.',
'Prepara due mini-interventi: presenta Nora, 12 anni, appassionata di disegno; racconta la sua domenica passata: visita alla nonna e partita a carte.',
['Presentazione al presente: “This is Nora. She is twelve. She likes drawing.”','Racconto al passato: “Last Sunday she visited her grandmother. Then she played cards.”','Uso una scaletta “who/age/interest” e una “when/first/then”; le leggo solo come parole guida.'],
'Presentazione: “This is Nora. She is twelve and she likes drawing.” Racconto: “Last Sunday she visited her grandmother. Then she played cards.”',
'Presenta Leo, 13 anni, amante della musica. Racconta il suo sabato scorso: pulizia della camera e ascolto di musica. Prova senza leggere frasi intere.',
'“This is Leo. He is thirteen. He likes music. Last Saturday he cleaned his room. Then he listened to music.” Criteri: dati completi, separazione presente/passato, ordine temporale; sono possibili frasi equivalenti.',
[('Separa i due scopi','Sul tuo compito scegli se presenti una persona o racconti eventi.','Una presentazione può essere al presente; un racconto passato va marcato.'),('Costruisci la scaletta','Scrivi tre parole per presentare e tre per raccontare.','Usa then per legare due eventi senza memorizzare un blocco unico.'),('Prova e ascolta','Pronuncia l’intervento e controlla dati, tempi e ordine con un ascoltatore.','Una pausa per guardare la scaletta è consentita durante l’apprendimento.')],
('Scaletta e recupero orale','Passa da frasi modello a parole guida, poi prova a ricostruire le frasi.','Sostiene l’ordine senza dipendere dalla lettura integrale.'),
['La presentazione contiene i dati richiesti','Il racconto segnala il tempo passato','Gli eventi sono ordinati'],
('Last Sunday she visit her grandmother.','L’indicazione è passata, ma il verbo è al presente.','Usa visited nel racconto e visits per un’abitudine.'),
'Usa due riquadri distinti con parole guida; consenti una pausa fra presentazione e racconto e la scaletta compensativa.',
'Sul tuo argomento orale prepara una scaletta e prova separatamente presentazione e racconto.',category='trasversale')

r('M11-05','Scrivere messaggio, e-mail, descrizione e racconto adattando contenuto e forma.',
'Usa questi dati: incontro sabato alle 15 al parco; amica Eva; luogo con due alberi e una panchina; ieri pioveva e il gruppo è rimasto a casa. Scrivi quattro testi brevi: messaggio, e-mail, descrizione, racconto.',
['Messaggio essenziale: “Hi Eva! Let’s meet in the park on Saturday at three.” E-mail con apertura e chiusura: “Dear Eva, Let’s meet in the park on Saturday at three. See you soon, Alex.”','Descrizione al presente: “The park has two trees and a bench.”','Racconto al passato: “Yesterday it rained. We stayed at home.” Controllo che ieri non diventi sabato.'],
'I quattro testi sopra sono completi per i dati assegnati: messaggio/e-mail propongono l’incontro; descrizione presenta il luogo; racconto riferisce eventi passati.',
'Dati nuovi: incontro lunedì alle 16 in biblioteca; amico Sam; biblioteca con tre tavoli; ieri visita a uno zio. Scrivi le stesse quattro forme.',
'Possibile soluzione: messaggio “Hi Sam! Let’s meet at the library on Monday at four.” E-mail “Dear Sam, Let’s meet at the library on Monday at four. See you soon, Alex.” Descrizione “The library has three tables.” Racconto “Yesterday I visited my uncle.” Controlla destinatario, luogo, giorno/ora e tempi.',
[('Scegli forma e destinatario','Nel tuo compito indica chi legge e se inviti, descrivi o racconti.','Non copiare un racconto dentro una descrizione senza segnare il passato.'),('Distribuisci i dati','Assegna ogni dato al testo che ne ha bisogno.','E-mail e messaggio condividono l’invito; solo e-mail richiede qui apertura e firma.'),('Rivedi in due giri','Prima controlla informazioni e forma, poi verbi, maiuscole e punteggiatura.','Non correggere tutte le parole mentre stai ancora decidendo il contenuto.')],
('Pianificazione per genere','Prepara quattro riquadri con scopo e dati prima di scrivere.','Rende esplicite le differenze fra produzioni richieste.'),
['Le quattro varianti sono riconoscibili','Giorno e ora sono corretti negli inviti','Descrizione e racconto usano tempi coerenti'],
('Yesterday I visit my uncle.','Il racconto riguarda ieri, quindi richiede un tempo passato.','Scrivi visited; controlla poi che l’invito resti al tempo adatto.'),
'Usa una lista breve di controllo ortografico e dizionario; se la scrittura è faticosa, detta prima il contenuto e correggi un tipo di errore alla volta.',
'Per il tuo testo prepara destinatario, scopo e tre informazioni prima della bozza.',category='disortografia',difficulty='Conosco la frase ma nella scrittura perdo lettere o desinenze')

r('M11-06','Applicare una regola grammaticale e distinguere affermazione, negazione e domanda.',
'Al present simple trasforma “She plays tennis” in negativa e interrogativa. Spiega che cosa accade alla -s.',
['Affermazione: she richiede plays con -s.','Negativa: “She does not play tennis.” Dopo does il verbo torna alla forma base play.','Domanda: “Does she play tennis?” Does precede she; play non ha -s.'],
'She plays tennis. She does not play tennis. Does she play tennis?',
'Trasforma “He reads books” in negativa e domanda. Scrivi anche la forma affermativa con They.',
'He does not read books. Does he read books? They read books. La -s resta solo nell’affermativa alla terza persona singolare.',
[('Identifica soggetto e forma','Nel tuo esercizio segna persona e richiesta: affermativa, negativa o domanda.','She è terza persona singolare; they no.'),('Applica la struttura','Scrivi soggetto + does not + base oppure does + soggetto + base.','Il segnale grammaticale è già in does.'),('Confronta le tre frasi','Verifica che significato lessicale e oggetto restino uguali.','Cambiano struttura e polarità, non lo sport.')],
('Confronto di strutture','Metti affermativa, negativa e domanda in tre righe evidenziando plays/play e does.','Mostra dove compare il segnale della terza persona.'),
['Soggetto e forma sono riconosciuti','Dopo does il verbo è alla base','La domanda ha ordine e punto interrogativo'],
('Does she plays tennis?','La -s è stata marcata due volte.','Usa Does she play tennis?.'),
'Tieni una tabella affermativa/negativa/domanda e una carta “dopo does: base”; controlla una struttura alla volta.',
'Su tre frasi del tuo corso cambia la forma e controlla il verbo dopo does.',category='disortografia')

r('M11-07','Imparare lessico in espressioni utili e recuperarlo dal significato.',
'Associa significato ed espressione: fare colazione = have breakfast; prendere l’autobus = take the bus; fare i compiti = do homework. Completa “I ___ breakfast at seven. I ___ the bus at eight. I ___ homework in the afternoon.”',
['Imparo i tre gruppi interi, non traduco solo i verbi isolati.','Completo have, take, do seguendo l’espressione.','Copro l’inglese e ricostruisco ogni gruppo dal significato italiano; poi li inserisco nelle frasi.'],
'I have breakfast at seven. I take the bus at eight. I do homework in the afternoon.',
'Nuovi gruppi: andare a letto = go to bed; ascoltare musica = listen to music; giocare a calcio = play football. Completa “I ___ at ten. I ___ after school. I ___ on Saturdays.”',
'I go to bed at ten. I listen to music after school. I play football on Saturdays. Devono comparire anche to nei primi due gruppi quando richiesto.',
[('Raccogli gruppi utili','Nel tuo elenco scrivi verbo e parole che lo accompagnano.','Listen to music include to.'),('Crea una frase','Usa ogni gruppo in una situazione breve e chiara.','Una frase aiuta a ricordare l’uso, non soltanto la traduzione.'),('Recupera e controlla','Copri l’inglese, prova dal significato e scopri solo dopo.','Segna i gruppi non recuperati per il ripasso.')],
('Recupero in contesto','Usa carte italiano/inglese con espressioni complete e poi frasi a spazio vuoto.','Allena a richiamare parole utilizzabili nella produzione.'),
['L’espressione è completa','La frase mantiene il significato','La risposta è tentata prima del confronto'],
('I make homework.','Il modello dato usa do homework, non make.','Ripeti e usa il gruppo intero do homework in una frase.'),
'Limita il blocco a tre espressioni, con significato e frase leggibili; usa audio del corso se la lettura interferisce.',
'Dal tuo lessico scegli tre gruppi frequenti e costruisci tre frasi di recupero.')

r('M11-08','Usare un modello ascoltato per distinguere pronuncia e intonazione.',
'Un lettore competente o audio del corso pronuncia “I can swim.” e “Can you swim?”. Ascolta, segna le parole su cui senti rilievo e ripeti. Confronta anche ship e sheep come coppia, senza trascrizioni italiane.',
['Distinguo l’affermazione dalla domanda prima di imitare il modello. In una domanda sì/no isolata il modello può usare una salita finale, non è una regola di ogni domanda.','Per ship/sheep ascolto la qualità vocalica e la durata nel modello; non riduco la differenza solo a “i breve/lunga”.','Ripeto un elemento per volta e chiedo al lettore quale parola ha riconosciuto; correggo dal modello sonoro, non dall’ortografia italiana.'],
'Produzione esemplificativa: affermazione e domanda riconoscibili nel modello scelto; ship e sheep riconosciute come parole diverse dall’ascoltatore. Senza ascolto reale non si dichiara la pronuncia verificata.',
'Con un modello competente ascolta e ripeti “I can dance.” e “Can you dance?”. Prova sit e seat. L’ascoltatore deve indicare quale parola sente senza vederla.',
'Criteri: affermazione/domanda distinte per struttura e intonazione coerente con il modello; sit/seat riconoscibili con qualità vocalica diversa. Una verifica scritta dei quattro testi non basta; registra esito dell’ascoltatore, anche “non ancora distinto”.',
[('Ascolta prima di leggere','Nel tuo esercizio confronta un breve modello sonoro e il testo.','Non inventare la pronuncia da una scrittura italiana approssimata.'),('Imita un segmento','Ripeti una parola o un gruppo, poi la frase.','Concentrati su una sola differenza per volta.'),('Chiedi riconoscimento','Fai scegliere all’ascoltatore fra due parole senza mostrargli la tua scelta.','Se non distingue, riascolta e riprova invece di aumentare solo il volume.')],
('Ascolto-imitazione-confronto','Alterna modello e produzione su una sola coppia e verifica la parola riconosciuta.','Fornisce un controllo esterno dell’intelligibilità.'),
['È stato ascoltato un modello reale','La differenza è controllata dall’ascoltatore','Non si usa una trascrizione italiana come prova'],
('Sheep è solo ship pronunciato più forte.','L’accento di volume non sostituisce la distinzione vocalica.','Confronta la vocale nel modello e chiedi riconoscimento senza testo visibile.'),
'Concedi più riascolti brevi e testo separato dal momento di ascolto; non valutare la velocità di ripetizione.',
'Riprendi una sola coppia dal tuo corso con un modello reale; se manca, prepara le parole ma rinvia il controllo sonoro.',category='trasversale',difficulty='Non riesco a distinguere due suoni ascoltandoli una sola volta')

r('M11-09','Confrontare una pratica culturale descritta senza trasformarla in stereotipo.',
'Testo didattico originale, su una scuola immaginaria: “At River School, some pupils eat a packed lunch. Others buy lunch in the school canteen. Lessons start at nine.” Elenca tre dati e formula una domanda di confronto con la tua scuola, senza generalizzare a tutto un Paese.',
['Rilevo some e others: esistono almeno due modalità di pranzo nella scuola descritta.','Registro orario: le lezioni iniziano alle nove.','Domanda di confronto: “Where do pupils eat lunch in our school?” Limito le conclusioni a River School, non a tutte le scuole anglofone.'],
'Dati: alcuni portano il pranzo; altri lo comprano in mensa; in quella scuola le lezioni iniziano alle nove. Domanda pertinente sul pranzo nella propria scuola.',
'Testo originale su un club immaginario: “At Lake Club, children borrow books on Thursdays. Some read stories; others choose comics.” Scrivi due dati e una domanda di confronto; indica che cosa non puoi concludere.',
'Dati: prestito il giovedì; alcuni scelgono racconti, altri fumetti. Domanda: “What books do children choose in our library?” Non puoi concludere che tutti i bambini di un Paese leggano fumetti o che il prestito sia sempre giovedì.',
[('Identifica la fonte e il luogo','Nel testo culturale scrivi a chi o a quale luogo si riferisce.','L’esempio è immaginario: non è una descrizione di un sistema nazionale.'),('Cerca somiglianze e differenze','Confronta una pratica precisa, non il valore delle persone.','Pranzo portato e mensa possono coesistere.'),('Limita la conclusione','Conserva parole come some e in this school.','Una pratica di un gruppo non descrive tutti gli abitanti.')],
('Confronto contestualizzato','Usa le colonne “nel testo”, “nel contesto che confronto”, “non so”.','Aiuta a separare informazione e generalizzazione.'),
['Il contesto è nominato','Some/others non diventano everyone','La domanda confronta una pratica precisa'],
('Tutti gli inglesi portano il pranzo da casa.','Il testo è immaginario e parla solo di alcuni alunni di una scuola.','Scrivi “In River School, some pupils…” e cerca fonti specifiche per domande reali.'),
'Metti luogo e parole di quantità in un riquadro; usa una tabella di confronto con una riga per ogni pratica.',
'Sul testo culturale assegnato indica il contesto e una conclusione che non è giustificata.')

r('M11-10','Tradurre frasi per significato controllando persona, tempo e negazione.',
'Traduci: “Mia sorella non gioca a tennis il lunedì.” e “Ieri abbiamo visitato un museo.”',
['Prima frase: soggetto my sister; abitudine al presente; negazione con does not; verbo base play.','Scrivo “My sister does not play tennis on Mondays.”','Seconda frase: ieri indica passato; “Yesterday we visited a museum.” Rileggo in italiano per controllare i dati.'],
'My sister does not play tennis on Mondays. Yesterday we visited a museum.',
'Traduci “Mio fratello non legge fumetti la domenica.” e “Ieri ho ascoltato musica.”',
'My brother does not read comics on Sundays. Yesterday I listened to music. Accettabili doesn’t e una formulazione equivalente che mantenga soggetto, negazione e tempo.',
[('Scomponi il significato','Nella tua frase indica chi, azione, tempo e presenza di negazione.','Non tradurre una parola isolata prima di sapere la struttura.'),('Costruisci l’inglese','Scegli prima il tempo e poi l’ordine delle parole.','Con does not usa il verbo base.'),('Ritraduci per controllo','Rileggi il significato italiano della frase ottenuta.','Controlla che ieri non diventi oggi e che non sia sparita la negazione.')],
('Traduzione per unità di senso','Prepara blocchi soggetto/azione/tempo e ricostruisci la frase inglese.','Evita la copia dell’ordine italiano quando la struttura cambia.'),
['Soggetto e azione sono mantenuti','Tempo e negazione restano corretti','Il verbo segue la struttura inglese'],
('My sister not plays tennis.','Manca l’ausiliare della negativa al present simple.','Usa My sister does not play tennis.'),
'Usa quattro caselle di significato e un modello di struttura; dizionario disponibile senza chiedere traduzione parola per parola.',
'Per due frasi del tuo compito registra tempo e negazione prima di tradurre.')

r('M11-11','Rappresentare un dialogo con ruoli, obiettivo e risposta comprensibile.',
'Scena in libreria: cliente chiede un quaderno blu; venditore lo offre a 3 euro; cliente compra e ringrazia. Scrivi e rappresenta sei battute.',
['Definisco ruoli e scopo: acquisto di un quaderno, non una conversazione libera.','Cliente: “Hello. A blue notebook, please.” Venditore: “Here you are.” Cliente: “How much is it?”','Venditore: “It’s three euros.” Cliente: “I’ll take it. Thank you.” Venditore: “You’re welcome.” Controllo oggetto, colore e prezzo.'],
'Sei battute nell’ordine mostrato; vendita conclusa con notebook blu e prezzo di 3 euro.',
'Scena al bar: cliente chiede un succo d’arancia; cameriere lo offre a 2 euro; cliente accetta e ringrazia. Scrivi sei battute e poi cambia i ruoli.',
'“Hello. An orange juice, please.” “Here you are.” “How much is it?” “It’s two euros.” “I’ll take it. Thank you.” “You’re welcome.” Varianti cortesi equivalenti ammesse; oggetto e prezzo devono rimanere quelli della consegna.',
[('Definisci la scena','Per il tuo dialogo assegna i ruoli e la richiesta da soddisfare.','Segna chi conosce il prezzo.'),('Scrivi le battute','Metti una funzione per turno: saluto/richiesta/offerta/domanda/risposta/chiusura.','Una risposta di prezzo deve seguire How much?.'),('Rappresenta e cambia','Prova con il testo, poi con carte di funzione e inverti i ruoli.','La recitazione non richiede memorizzare tutto senza aiuti.')],
('Copione funzionale','Accanto a ogni battuta scrivi a che cosa serve e usa quelle etichette nella seconda prova.','Collega le frasi allo scopo comunicativo.'),
['Ogni battuta risponde alla precedente','Oggetto e prezzo sono coerenti','Entrambi i ruoli sono rappresentati'],
('How much is it? — It is blue.','La domanda chiede il prezzo, non il colore.','Rispondi It’s three euros; usa blue nella richiesta.'),
'Dai una carta per ruolo con parole chiave e numero del turno; lascia visibili le formule cortesi.',
'Ripeti un dialogo scolastico cambiando un oggetto e un prezzo, poi scambia i ruoli.',category='trasversale')

r('M12-01','Comprendere brevi ascolti e testi nella seconda lingua cercando dati precisi.',
'Scegli la lingua che studi. Per ascolto fai leggere due volte senza vedere il copione; per testo leggi tu. FR: “Je m’appelle Zoé. J’ai douze ans. Je vais à la piscine le samedi.” ES: “Me llamo Ana. Tengo doce años. Voy a la piscina los sábados.” DE: “Ich heiße Lina. Ich bin zwölf Jahre alt. Ich gehe samstags ins Schwimmbad.” Trova nome, età, luogo e giorno.',
['Preparo quattro caselle prima di leggere o ascoltare.','FR: Zoé, douze, piscine, samedi. ES: Ana, doce, piscina, sábados. DE: Lina, zwölf, Schwimmbad, samstags.','Controllo l’età: francese e spagnolo usano avoir/tener; tedesco usa sein nella formulazione data. Non trasferisco automaticamente la struttura fra lingue.'],
'FR: Zoé, 12 anni, piscina, sabato. ES: Ana, 12 anni, piscina, sabati. DE: Lina, 12 anni, piscina, sabati. Le tre versioni sono alternative.',
'Nuovi copioni/testi. FR: “Je m’appelle Louis. J’ai treize ans. Je vais au parc le dimanche.” ES: “Me llamo Luis. Tengo trece años. Voy al parque los domingos.” DE: “Ich heiße Lukas. Ich bin dreizehn Jahre alt. Ich gehe sonntags in den Park.” Cerca gli stessi quattro dati nella lingua scelta.',
'FR Louis, ES Luis, DE Lukas; 13 anni; parco; domenica/domeniche. Per l’ascolto il copione resta nascosto e il confronto si fa dopo; letto autonomamente verifica solo comprensione scritta.',
[('Scegli lingua e modalità','Nel tuo esercizio indica se ascolti o leggi e prepara le caselle.','Lavora in una sola lingua per volta.'),('Cerca i quattro dati','Prima identifica il tema, poi nome, età, luogo e giorno.','Non serve tradurre ogni parola.'),('Confronta con il testo','Dopo il tentativo controlla il dato incerto nel copione.','In ascolto non anticipare il testo; in lettura cerca la frase prova.')],
('Comprensione orientata','Usa quattro domande uguali e le espressioni della lingua studiata per localizzare i dati.','Rende il compito specifico e confrontabile.'),
['La modalità ascolto/lettura è esplicita','I quattro dati seguono il testo scelto','L’età non è tradotta con una struttura trasferita a caso'],
('Ich habe zwölf Jahre per dire l’età nel modello tedesco.','È un calco dalla struttura di altre lingue e non è la formula data.','Usa Ich bin zwölf Jahre alt; in francese J’ai douze ans e in spagnolo Tengo doce años.'),
'Usa una tabella di quattro domande e, nell’ascolto, una lettura con pause fra le frasi; nella lettura usa il segnariga.',
'Sul tuo breve testo prepara nome, età, luogo e tempo; distingui sul quaderno lettura e ascolto.')

r('M12-02','Associare vocaboli a immagini e richiamarli con articolo nella lingua studiata.',
'Tre immagini sono descritte integralmente: A animale che miagola; B oggetto legato di fogli da leggere; C sedile con schienale. Associa le parole. FR: le livre, la chaise, le chat. ES: la silla, el gato, el libro. DE: die Katze, das Buch, der Stuhl.',
['Riconosco i significati delle tre immagini prima delle etichette.','FR: A le chat, B le livre, C la chaise. ES: A el gato, B el libro, C la silla. DE: A die Katze, B das Buch, C der Stuhl.','Copro le parole e le recupero dalla descrizione, mantenendo l’articolo; il genere grammaticale può cambiare fra lingue.'],
'Associazioni A/B/C come sopra; gli articoli fanno parte delle etichette da imparare.',
'Immagini descritte: D animale che abbaia; E tavolo con quattro gambe; F automobile. FR: la voiture, le chien, la table. ES: la mesa, el coche, el perro. DE: der Hund, das Auto, der Tisch. Associa e recupera dalla descrizione.',
'FR D le chien, E la table, F la voiture. ES D el perro, E la mesa, F el coche. DE D der Hund, E der Tisch, F das Auto. Disegni stilizzati o descrizioni valgono se identificano gli stessi oggetti.',
[('Identifica l’immagine','Nel tuo compito nomina l’oggetto in italiano o descrivilo prima di scegliere.','Un dettaglio decorativo non cambia l’oggetto.'),('Abbina con articolo','Collega ogni immagine al gruppo articolo + nome della tua lingua.','DE richiede der/die/das; non scegliere dal genere italiano.'),('Recupera senza elenco','Copri le etichette e ripeti da immagine o descrizione.','Scopri dopo e correggi il gruppo completo.')],
('Associazione e recupero','Dopo l’abbinamento inverti la direzione: immagine → articolo e parola.','Verifica il richiamo, oltre il riconoscimento fra alternative.'),
['Ogni immagine ha l’etichetta giusta','L’articolo appartiene alla lingua scelta','Il recupero avviene prima del confronto'],
('In tedesco scrivo die Buch perché libro in un’altra lingua ha un altro genere.','Il genere non si ricava trasferendo quello di un’altra lingua.','Impara das Buch come gruppo.'),
'Disponi una sola immagine e tre parole per volta, con etichette ampie e articolo visibile; puoi ascoltare la parola modello.',
'Per tre immagini del tuo corso prepara etichette con articolo e prova il richiamo dopo averle coperte.')

r('M12-03','Presentarsi con nome, età e provenienza nella lingua studiata.',
'Personaggio inventato: Sofia, 12 anni, abita a Roma. Presentala in prima persona nella tua seconda lingua.',
['FR: nome con “Je m’appelle Sofia”, età con “J’ai douze ans”, luogo con “J’habite à Rome”.','ES: “Me llamo Sofia. Tengo doce años. Vivo en Roma.”','DE: “Ich heiße Sofia. Ich bin zwölf Jahre alt. Ich wohne in Rom.” Scelgo solo la versione della lingua studiata.'],
'FR: Je m’appelle Sofia. J’ai douze ans. J’habite à Rome. ES: Me llamo Sofia. Tengo doce años. Vivo en Roma. DE: Ich heiße Sofia. Ich bin zwölf Jahre alt. Ich wohne in Rom.',
'Personaggio inventato: Marco, 13 anni, abita a Milano. Presentalo in prima persona; non usare dati personali reali.',
'FR: Je m’appelle Marco. J’ai treize ans. J’habite à Milan. ES: Me llamo Marco. Tengo trece años. Vivo en Milán. DE: Ich heiße Marco. Ich bin dreizehn Jahre alt. Ich wohne in Mailand. Si accetta il nome locale della città usato dal corso se coerente.',
[('Prepara i dati fittizi','Sul tuo compito scrivi nome, età e luogo del personaggio.','Non devi raccontare dati personali per imparare la struttura.'),('Scegli tre formule','Usa il modello della tua lingua e sostituisci un dato alla volta.','FR/ES hanno “avere” nell’età; DE “essere”.'),('Presenta e controlla','Pronuncia le tre frasi da una carta con parole chiave e verifica i dati.','La carta può restare disponibile come strumento.')],
('Sostituzione guidata','Mantieni tre formule e cambia nome, numero e città, poi prova senza frasi complete.','Allena una presentazione trasferibile a nuovi dati.'),
['Tutti e tre i dati sono presenti','L’età usa la formula della lingua scelta','La prima persona resta coerente'],
('Je suis douze ans.','La formula francese dell’età usa avoir.','Scrivi J’ai douze ans; non copiare la struttura tedesca.'),
'Usa tre carte nome/età/luogo e un modello breve per ciascuna; puoi rispondere a domande prima di unire le frasi.',
'Presenta un personaggio del tuo libro con tre parole guida e controlla la formula dell’età.',category='trasversale')

r('M12-04','Gestire una richiesta quotidiana con formula cortese e risposta.',
'Scena: vuoi un succo, il prezzo è 2 euro. Scrivi e prova richiesta e domanda sul prezzo. FR: jus; ES: zumo; DE: Saft.',
['FR: “Un jus, s’il vous plaît.” “Combien ça coûte ?” Risposta: “Deux euros.”','ES: “Un zumo, por favor.” “¿Cuánto cuesta?” Risposta: “Dos euros.”','DE: “Einen Saft, bitte.” “Wie viel kostet das?” Risposta: “Zwei Euro.” In tedesco einen segnala l’accusativo maschile della richiesta ellittica.'],
'Tre mini-dialoghi alternativi con richiesta, prezzo e cortesia. Chiusure: Merci / Gracias / Danke.',
'Scena nuova: vuoi un panino a 3 euro. Parole e forma richiesta: FR un sandwich; ES un bocadillo; DE ein Sandwich (neutro). Scrivi richiesta, domanda sul prezzo e risposta nella tua lingua.',
'FR “Un sandwich, s’il vous plaît. Combien ça coûte ?” “Trois euros.” ES “Un bocadillo, por favor. ¿Cuánto cuesta?” “Tres euros.” DE “Ein Sandwich, bitte. Wie viel kostet das?” “Drei Euro.” Aggiungi Merci/Gracias/Danke.',
[('Definisci la richiesta','Sul tuo esercizio scrivi oggetto, prezzo e chi chiede o risponde.','Non devi acquistare davvero: prova su carta.'),('Usa la formula cortese','Adatta l’oggetto al modello della tua lingua.','ES ha ¿ all’inizio della domanda; DE può cambiare l’articolo.'),('Scambia i ruoli','Prova richiesta, prezzo e ringraziamento, poi inverti cliente e venditore.','Controlla che il prezzo risponda alla domanda.')],
('Dialogo per funzioni','Metti richiesta, domanda, prezzo e ringraziamento in quattro carte.','Sostiene l’interazione anche cambiando l’oggetto.'),
['Richiesta e prezzo corrispondono','La formula cortese è presente','Articoli e segni seguono la lingua scelta'],
('In tedesco chiedo Ein Saft, bitte usando lo stesso articolo del soggetto.','Nel modello di richiesta l’oggetto maschile è all’accusativo.','Usa Einen Saft, bitte; confronta il neutro Ein Sandwich.'),
'Lascia disponibili formule e articolo del nome; usa carte di ruolo anziché un copione da ricordare interamente.',
'Nel tuo dialogo quotidiano cambia un oggetto e il prezzo, mantenendo le formule cortesi.',category='trasversale')

r('M12-05','Scrivere cartolina, messaggio ed e-mail con dati, destinatario e registro adatti.',
'Personaggio Alex è a Roma, gli piace la città, invita l’amico Luca al parco sabato. Scrivi cartolina, messaggio e breve e-mail nella lingua studiata.',
['Cartolina descrittiva: FR “Salut Luca ! Je suis à Rome. J’aime la ville. À bientôt, Alex.” ES “¡Hola, Luca! Estoy en Roma. Me gusta la ciudad. Hasta pronto, Alex.” DE “Hallo Luca! Ich bin in Rom. Die Stadt gefällt mir. Bis bald, Alex.”','Messaggio d’invito: FR “Salut Luca ! On va au parc samedi ?” ES “¡Hola, Luca! ¿Vamos al parque el sábado?” DE “Hallo Luca! Gehen wir am Samstag in den Park?”','E-mail: uso la stessa domanda del messaggio, apertura e firma; oggetto FR “Samedi”, ES “El sábado”, DE “Samstag”.'],
'E-mail esemplificative: FR “Salut Luca, On va au parc samedi ? À bientôt, Alex.” ES “Hola, Luca: ¿Vamos al parque el sábado? Hasta pronto, Alex.” DE “Hallo Luca, gehen wir am Samstag in den Park? Bis bald, Alex.” Cartolina e messaggio sono quelli dei passaggi; l’e-mail contiene anche un oggetto.',
'Personaggio Sara è a Milano, le piace la città, invita l’amica Eva in biblioteca domenica. Scrivi le tre forme. Lessico: FR bibliothèque; ES biblioteca; DE Bibliothek.',
'Cartolina: FR “Salut Eva ! Je suis à Milan. J’aime la ville. À bientôt, Sara.” ES “¡Hola, Eva! Estoy en Milán. Me gusta la ciudad. Hasta pronto, Sara.” DE “Hallo Eva! Ich bin in Mailand. Die Stadt gefällt mir. Bis bald, Sara.” Invito: FR “On va à la bibliothèque dimanche ?” ES “¿Vamos a la biblioteca el domingo?” DE “Gehen wir am Sonntag in die Bibliothek?” Messaggio con saluto; e-mail con oggetto, saluto, invito e firma. Le tre forme devono essere riconoscibili.',
[('Scegli lo scopo','Per il tuo testo segna cartolina descrittiva oppure invito in messaggio/e-mail.','Una cartolina qui dice dove sei; l’invito dice luogo e giorno.'),('Inserisci dati e formule','Sostituisci persona, città, luogo e giorno nel modello della tua lingua.','Non mescolare le tre lingue nella stessa frase.'),('Rivedi la forma','Controlla oggetto dell’e-mail, apertura, dati e chiusura.','FR conserva accenti; ES usa segni iniziali; DE scrive i nomi con maiuscola.')],
('Modelli per genere','Confronta tre testi con gli stessi dati e conserva solo le parti pertinenti a ciascuno.','Mostra come il formato cambia l’organizzazione del contenuto.'),
['Cartolina, messaggio ed e-mail sono distinti','Gli inviti conservano luogo e giorno','Le convenzioni della lingua sono controllate'],
('In spagnolo scrivo Me gusto la ciudad per “mi piace la città”.','Nel modello il soggetto grammaticale è la città: gusta.','Usa Me gusta la ciudad e confronta la frase modello.'),
'Tieni un modello per la sola lingua studiata e una lista di due controlli ortografici pertinenti; correggi dopo la bozza.',
'Per il tuo scritto prepara prima destinatario, scopo e dati; usa il modello del genere richiesto.',category='disortografia')

r('M12-06','Coniugare una frase semplice e negarla con la struttura della lingua studiata.',
'Trasforma alla prima persona e poi in negativa: FR “Elle aime la musique”; ES “Ella habla español”; DE “Sie spielt Tennis”. Lavora nella lingua del tuo corso.',
['FR: “J’aime la musique.” Negativa scritta standard: “Je n’aime pas la musique.” n’ precede aime e pas segue il verbo.','ES: “Hablo español.” Negativa: “No hablo español.” Il soggetto yo può essere espresso, ma qui è omesso.','DE: “Ich spiele Tennis.” Negativa: “Ich spiele kein Tennis.” Con il nome Tennis senza articolo uso qui kein; nella frase dichiarativa il verbo coniugato è in seconda posizione.'],
'FR J’aime / Je n’aime pas la musique. ES Hablo / No hablo español. DE Ich spiele Tennis / Ich spiele kein Tennis.',
'Prima persona e negativa: FR “Elle habite à Paris”; ES “Ella estudia francés”; DE “Sie wohnt in Berlin”.',
'FR “J’habite à Paris. Je n’habite pas à Paris.” ES “Estudio francés. No estudio francés.” DE “Ich wohne in Berlin. Ich wohne nicht in Berlin.” La negazione deve riguardare l’informazione data; non cambia la città o la lingua.',
[('Identifica persona e verbo','Nel tuo esercizio segna il verbo e il soggetto richiesto.','FR/ES/DE hanno desinenze diverse: usa la tabella della tua lingua.'),('Coniuga e nega','Costruisci prima l’affermativa, poi aggiungi la negazione nel posto previsto.','Non mettere no in tedesco o nicht in francese.'),('Rileggi il significato','Controlla persona, oggetto e informazione negata.','La frase negativa non deve perdere il resto dei dati.')],
('Trasformazione affermativa-negativa','Affianca due righe e marca posizione del verbo e parole di negazione.','Fa vedere la struttura invece di memorizzare frasi isolate.'),
['La prima persona è corretta','La negazione segue la lingua scelta','Gli altri dati restano invariati'],
('Je aime no la musique.','Manca l’elisione e la negazione è trasferita da un’altra lingua.','Usa J’aime e, nella negativa standard scritta, Je n’aime pas la musique.'),
'Usa un modello con spazi per soggetto, verbo e negazione; lascia visibile la tabella del verbo studiato.',
'Trasforma tre frasi del tuo corso e confronta solo persona e negazione nel primo controllo.',category='disortografia')

r('M12-07','Confrontare pronuncia e ortografia senza usare equivalenze fra lingue come regole.',
'Scegli la tua lingua e ascolta un modello competente. FR: “chat”, “chats”, “école”; ES: “hola”, “niño”, “mañana”; DE: “Schule”, “schön”, “Buch”. Osserva le grafie e ripeti i gruppi senza trascriverli con lettere italiane.',
['FR: in questi nomi isolati il plurale scritto chats non aggiunge una s pronunciata; é di école è un segno da conservare.','ES: h di hola non si pronuncia nel modello standard; ñ di niño/mañana è una lettera distinta da n.','DE: sch di Schule corrisponde al suono iniziale modellato; ö di schön non equivale a o; i nomi Buch e Schule si scrivono con iniziale maiuscola. Confronto sempre col suono reale.'],
'Controllo scritto: chats, école; hola, niño, mañana; Schule, schön, Buch. Controllo orale: l’ascoltatore riconosce le parole nella lingua scelta; senza modello e ascoltatore si verifica solo la grafia.',
'Nuove parole da un modello competente: FR “amis”, “été”; ES “hombre”, “año”; DE “Fisch”, “Tür”. Copia correttamente, ascolta e ripeti; spiega un tratto della tua lingua.',
'FR conserva é in été; la s finale di amis non si pronuncia nella parola isolata del modello standard (non estendere a ogni contesto di liaison). ES h di hombre muta, ñ di año distinta da n. DE sch in Fisch, ü in Tür distinta da u, nomi con maiuscola. Pronuncia da verificare realmente nel modello, non dal solo testo.',
[('Scegli il modello','Usa il parlante o audio del tuo corso e seleziona due parole.','Non mescolare accenti o lingue per la stessa prova.'),('Confronta suono e grafia','Ascolta, poi segna il dettaglio scritto che non puoi dedurre dall’italiano.','Un accento o un umlaut non è una decorazione.'),('Ripeti e ricopia','Verifica oralmente con ascoltatore e graficamente con la parola modello, in due controlli separati.','Un controllo corretto non garantisce automaticamente l’altro.')],
('Confronto suono-segno','Affianca parola modello e produzione scritta dopo un ascolto reale.','Distingue riconoscimento del suono e conservazione della grafia.'),
['Accenti, ñ o umlaut sono conservati','Le maiuscole tedesche sono controllate','La pronuncia è valutata solo con ascolto reale'],
('Scrivo ano al posto di año pensando che n e ñ siano equivalenti.','In spagnolo sono lettere diverse e possono cambiare la parola.','Confronta año col modello e conserva ñ.'),
'Disponi due parole per volta con dettaglio grafico evidenziato; usa tastiera o caratteri già disponibili se tracciare il segno ostacola il controllo.',
'Su due parole del tuo corso separa un controllo di ascolto da un controllo ortografico.',category='disortografia')

r('M12-08','Ricavare aspetti culturali da un testo delimitato e confrontarli senza stereotipi.',
'Tre testi didattici originali descrivono club immaginari. FR: “Dans notre club, certains élèves lisent des bandes dessinées le mercredi.” ES: “En nuestro club, algunos alumnos leen cómics los viernes.” DE: “In unserem Club lesen einige Schüler samstags Comics.” Trova chi, che cosa e quando; limita la conclusione al club.',
['FR: alcuni alunni leggono fumetti il mercoledì. ES: alcuni alunni leggono fumetti il venerdì. DE: alcuni alunni leggono fumetti il sabato.','Conservo certains/algunos/einige: non significa tutti.','Confronto la pratica, non una nazione: una domanda possibile è “In quali giorni il nostro gruppo legge insieme?” I club sono immaginari.'],
'Tre pratiche alternative: fumetti in un club, con giorni diversi e partecipazione di alcuni alunni. Nessuna descrive tutti i giovani di Francia, Spagna o Germania.',
'Nuovi testi originali su biblioteche immaginarie. FR: “Dans cette bibliothèque, certains enfants empruntent des livres le lundi.” ES: “En esta biblioteca, algunos niños toman libros prestados los martes.” DE: “In dieser Bibliothek leihen einige Kinder mittwochs Bücher aus.” Ricava pratica e giorno, poi scrivi una domanda di confronto.',
'Prestito di libri: FR lunedì; ES martedì; DE mercoledì. Riguarda alcuni bambini della biblioteca descritta. Domanda pertinente: “Quando è possibile prendere libri in prestito nella biblioteca che conosco?” Non dedurre un calendario nazionale.',
[('Delimita il contesto','Nel tuo testo segna luogo, gruppo e parole di quantità.','Questi esempi sono immaginari: servono a imparare il confronto.'),('Estrai la pratica','Scrivi attività e giorno dalla lingua studiata.','DE: il verbo ausleihen è separato in leihen…aus nella frase data.'),('Confronta con prudenza','Formula una domanda su una pratica simile e indica ciò che non sai.','Per un’affermazione reale su un Paese servono fonti adeguate.')],
('Lettura culturale contestualizzata','Compila chi/luogo/pratica/giorno e conserva le parole che limitano il gruppo.','Evita di trasformare un testo locale in uno stereotipo.'),
['La pratica è tradotta correttamente','Le parole “alcuni” sono conservate','Il confronto non è una generalizzazione nazionale'],
('In Germania tutti leggono fumetti il sabato.','Il testo riguarda alcuni membri di un club immaginario.','Scrivi “Nel club descritto, alcuni…” e lascia aperta la domanda sugli altri contesti.'),
'Usa una tabella con luogo, gruppo, pratica e giorno; evidenzia alcuni nella lingua del testo.',
'Nel tuo testo culturale sottolinea il contesto e prepara una domanda, non una regola su tutti gli abitanti.')

r('M13-01','Collegare materiale, energia e funzione in un sistema tecnologico.',
'Una torcia descritta ha corpo di plastica, contatti metallici, pile, interruttore e lampada LED. Spiega la funzione di due materiali e la trasformazione energetica; non aprire né modificare un dispositivo reale.',
['Il corpo di plastica contiene i componenti e, nell’uso previsto, isola dai contatti; i contatti metallici conducono corrente.','Le pile forniscono energia al circuito chiuso dall’interruttore; il LED trasforma parte dell’energia elettrica in luce e parte in calore.','Schema del sistema: pile → circuito/interruttore → LED → luce e calore. Il corpo protegge e sostiene, ma non fornisce l’energia.'],
'Materiali diversi svolgono funzioni diverse. La torcia usa energia immagazzinata nelle pile e produce luce con dissipazione in calore.',
'Un ventilatore descritto ha scocca di plastica, fili metallici e motore alimentato a batteria. Spiega materiale, energia e funzione senza realizzare un circuito.',
'Plastica: contenimento/protezione nell’uso previsto; metallo dei fili: conduzione. Batteria → energia elettrica → motore → movimento delle pale, con produzione anche di calore e suono. Non si conclude che tutta l’energia diventi movimento.',
[('Elenca i componenti','Sul tuo oggetto separa materiale, componente e funzione.','“Metallo” è il materiale, “contatto” il componente.'),('Segui l’energia','Indica fonte, passaggi e risultati del funzionamento.','Distingui energia da oggetti: il LED non è una forma di energia.'),('Spiega una scelta','Collega una proprietà del materiale alla funzione.','Non basta dire che la plastica è economica se la consegna chiede isolamento.')],
('Schema funzionale','Disegna una catena energetica e una tabella materiale-funzione.','Collega parti e trasformazioni senza confondere i livelli.'),
['Materiali e componenti sono distinti','La fonte energetica è corretta','Sono indicate funzione e almeno una dissipazione'],
('Le pile contengono luce che entra nel LED.','La luce è prodotta durante il funzionamento, non conservata come luce nelle pile.','Rappresenta la fonte e la trasformazione in energia elettrica, poi luce e calore.'),
'Usa carte separate per materiale, funzione e energia; collega una relazione per volta senza dover tenere l’intero sistema in mente.',
'Per un oggetto del tuo libro compila due righe materiale-funzione e una catena energetica.')

r('M13-02','Rappresentare un processo produttivo e uno schema di funzionamento con frecce diverse.',
'Dati: un quaderno si produce preparando carta, stampando righe, tagliando fogli, raccogliendoli e rilegandoli con una copertina. Una lampada da tavolo descritta funziona con fonte elettrica, interruttore e lampadina. Disegna due schemi: produzione del quaderno e funzionamento della lampada.',
['Produzione: carta → stampa delle righe → taglio → raccolta dei fogli → rilegatura con copertina → quaderno. Le frecce indicano successione delle operazioni.','Funzionamento: fonte elettrica → interruttore chiuso/circuito → lampadina → luce e calore. Le frecce indicano un flusso energetico semplificato.','Nomino i due schemi: uno dice come l’oggetto è fabbricato, l’altro come opera durante l’uso.'],
'Due schemi distinti e ordinati. Nel primo entrano materiali e lavorazioni; nel secondo fonte, controllo e risultato.',
'Dati: un sacchetto di carta si produce tagliando un foglio, piegandolo, incollando fondo e bordo, lasciando asciugare. Un campanello a batteria ha pulsante e segnalatore sonoro. Rappresenta produzione e funzionamento.',
'Produzione: foglio → taglio → piegatura → incollaggio fondo/bordo → asciugatura → sacchetto. Funzionamento: batteria → circuito chiuso dal pulsante → segnalatore → suono e calore. Le frecce non hanno lo stesso significato nei due schemi.',
[('Scegli il tipo di schema','Sul tuo compito indica se descrivi fabbricazione oppure uso.','Un interruttore non è una fase produttiva.'),('Ordina i passaggi','Scrivi azioni per la produzione, componenti e flussi per il funzionamento.','Usa il testo fornito; non aggiungere macchine non descritte.'),('Aggiungi una legenda','Dichiara se la freccia significa “poi” o “energia verso”.','Una freccia senza significato può confondere i due schemi.')],
('Diagramma con legenda','Usa riquadri numerati per le fasi e una catena separata per il funzionamento.','Rende esplicita la relazione fra i blocchi.'),
['Le fasi produttive rispettano l’ordine','Il funzionamento include fonte e risultato','La legenda distingue successione e flusso'],
('Produzione della lampada: accendo l’interruttore e si illumina.','È una descrizione del funzionamento durante l’uso.','Per la produzione cerca dati di assemblaggio; qui sono forniti quelli del quaderno.'),
'Prepara blocchi mobili con una parola per fase e la legenda scritta; riordina prima di ricopiare le frecce.',
'Per la pagina assegnata intitola esplicitamente il diagramma “produzione” o “funzionamento”.')

r('M13-03','Rappresentare viste di un oggetto rispettando dimensioni e scala.',
'Un blocco rettangolare è largo 6 cm, alto 4 cm e profondo 3 cm. Disegna in scala 1:1 vista frontale, dall’alto e laterale, indicandone dimensioni.',
['Scelgo il fronte: larghezza 6 e altezza 4 → rettangolo 6 × 4 cm.','Dall’alto vedo larghezza e profondità: 6 × 3 cm. La vista laterale mostra profondità e altezza: 3 × 4 cm.','Scrivo il nome di ogni vista e conservo le stesse dimensioni comuni; non inserisco la profondità nella vista frontale.'],
'Frontale 6 × 4 cm, dall’alto 6 × 3 cm, laterale 3 × 4 cm; scala 1:1.',
'Blocco largo 8 cm, alto 6 cm, profondo 4 cm. Disegna le tre viste in scala 1:2 e indica dimensioni reali e disegnate.',
'Frontale disegnata 4 × 3 cm, dall’alto 4 × 2 cm, laterale 2 × 3 cm. Quote reali: 8 × 6, 8 × 4, 4 × 6 cm. La scala dimezza il disegno, non l’oggetto.',
[('Definisci il fronte','Sul tuo oggetto indica larghezza, altezza e profondità prima delle viste.','Una freccia può mostrare da quale lato guardi.'),('Applica la scala','Calcola le lunghezze disegnate prima di tracciare.','1:2 significa metà della misura reale.'),('Allinea e quota','Mantieni dimensioni comuni coerenti e scrivi le misure reali nelle quote.','La disposizione delle viste segue la convenzione richiesta dal docente; qui sono nominate separatamente.')],
('Tabella dimensioni-viste','Prepara frontale L-H, alto L-P, laterale P-H con le misure reali e in scala.','Aiuta a selezionare le due dimensioni visibili in ciascuna vista.'),
['Ogni vista usa le due dimensioni corrette','La scala è applicata uniformemente','Le quote descrivono dimensioni reali'],
('Nella vista dall’alto disegno 6 × 4 come nel fronte.','Dall’alto la seconda dimensione è profondità, non altezza.','Disegna 6 × 3 e controlla la tabella L-P.'),
'Usa un modello di scatola e tre cornici etichettate; strumenti stabili per tracciare, lasciando al ragazzo la scelta delle dimensioni.',
'Prima di disegnare l’oggetto assegnato compila una tabella delle misure di ogni vista.',category='trasversale')

r('M13-04','Usare righello e squadra distinguendo linee di contorno, costruzione e quota.',
'Disegna un quadrato di lato reale 40 mm in scala 1:1. Nella convenzione didattica qui adottata, usa contorno continuo marcato, costruzioni sottili e quote esterne sottili con estremi indicati. Non sono richieste altre convenzioni normative.',
['Traccio i lati di 40 mm con righello e squadra, verificando perpendicolarità.','Tengo sottili le linee di costruzione; ripasso soltanto il contorno della figura finita.','Metto una linea di quota esterna parallela al lato, con estremi e numero 40; scrivo “quote in mm” e “scala 1:1”.'],
'Quadrato con contorno distinto dalle costruzioni; quota esterna 40 e unità mm dichiarata; scala 1:1.',
'Disegna un rettangolo reale 60 × 30 mm in scala 1:2, usando la stessa convenzione. Quanto misurano i lati disegnati? Quali numeri metti nelle quote?',
'Disegno 30 × 15 mm. Quote reali 60 e 30, non 30 e 15. Scala 1:2; “quote in mm”; linee di quota esterne e contorno distinto.',
[('Scegli lo strumento','Sul tuo disegno usa righello per misura e squadra per perpendicolari.','Il righello non garantisce da solo l’angolo retto.'),('Distingui i tratti','Disegna costruzioni leggere e ripassa il contorno dopo il controllo.','Non ripassare ogni linea indiscriminatamente.'),('Applica le convenzioni','Metti quote leggibili fuori dalla figura, unità e scala.','Se il docente usa una convenzione diversa, seguila in modo coerente.')],
('Lista di convenzioni','Tieni vicino al foglio tre campioni di linea: contorno, costruzione, quota.','Rende visibile la funzione del tratto senza affidarsi alla sola memoria.'),
['Righello e squadra hanno funzioni distinte','Contorno e costruzioni sono riconoscibili','Quote reali, unità e scala sono esplicite'],
('In scala 1:2 metto la quota 30 per il lato reale 60.','La quota indica la misura reale, non quella ridotta sul foglio.','Scrivi 60 nella quota e 1:2 nella scala.'),
'Usa righello/squadra con presa stabile e foglio fissato; modelli di tratti vicini alla zona di lavoro. Precisione del tratto e scelta della quota si osservano separatamente.',
'Sul tuo disegno fai tre controlli: tratti, quote reali, scala.',category='trasversale',difficulty='Il tratto è incerto e perdo la posizione dello strumento')

r('M13-05','Analizzare un oggetto collegando parti, funzione, materiali e limite.',
'Oggetto descritto: forbici scolastiche a punta arrotondata, con due lame metalliche, due anelli di plastica e un perno. Spiega parti e funzione; l’analisi non richiede usarle.',
['Le lame metalliche tagliano nel loro uso previsto; gli anelli permettono la presa.','Il perno unisce le due parti e permette la rotazione relativa. La forza delle dita muove le lame attraverso gli anelli.','Limite: punta arrotondata non significa oggetto privo di rischi; uso solo secondo le istruzioni e autorizzazioni scolastiche.'],
'Tabella: lame/metallo/taglio; anelli/plastica/presa; perno/collegamento/rotazione. Funzione complessiva: tagliare materiali adatti, non qualunque materiale.',
'Oggetto descritto: molletta da bucato con due leve di legno e una molla metallica. Spiega tre elementi, funzionamento e un limite.',
'Le due leve di legno offrono presa e superfici di contatto; molla metallica collega e mantiene la pressione. Premendo le estremità la molletta si apre; rilasciando stringe nel suo uso previsto. Limite: non garantisce presa su ogni spessore o carico; non usarla su parti del corpo.',
[('Scomponi l’oggetto','Nel tuo compito elenca le parti osservate e i materiali dichiarati.','Non inventare materiale o meccanismo di parti nascoste.'),('Collega parte e funzione','Scrivi come ogni parte contribuisce al risultato.','La funzione del perno non è tagliare.'),('Descrivi uso e limite','Spiega l’azione iniziale, il movimento e l’effetto, con un limite pertinente.','Descrivere non richiede provare l’oggetto se non è autorizzato.')],
('Tabella parte-materiale-funzione','Compila una riga per componente e poi unisci le funzioni nella spiegazione.','Evita un semplice elenco senza comprensione del funzionamento.'),
['Ogni parte ha funzione pertinente','Materiali noti e ignoti sono distinti','Il funzionamento e un limite sono espliciti'],
('Il perno serve a tagliare il foglio.','Il taglio è svolto dalle lame, il perno permette il loro movimento relativo.','Correggi la riga del perno e collega rotazione e lame.'),
'Usa un disegno etichettato o un’immagine con tre richiami; indica una parte per volta e puoi dettare la tabella.',
'Analizza un oggetto del libro usando almeno tre righe parte-materiale-funzione.')

r('M13-06','Progettare, realizzare e verificare un prodotto semplice rispetto a vincoli.',
'Progetta un segnalibro in cartoncino di 15 × 4 cm, con nome del progetto e un foro facoltativo a 1 cm dal bordo superiore. Usa carta/righello per la prova; taglio e foro solo con strumenti autorizzati e aiuto previsto.',
['Vincoli: rettangolo 15 × 4 cm, scritta leggibile; foro facoltativo che non indebolisca troppo il bordo. Disegno e segno misure prima di realizzare.','Prototipo su carta: traccio il rettangolo, posiziono titolo e punto del foro; verifico che la scritta stia nell’area.','Realizzazione autorizzata: riporto sul cartoncino e completo. Controllo misure, leggibilità e inserimento fra pagine senza danneggiarle; se manca autorizzazione consegno il prototipo su carta.'],
'Progetto esemplificativo “Leggo qui”: rettangolo 15 × 4 cm, scritta centrale e foro facoltativo segnato a 1 cm dal bordo superiore. La prova di uso controlla i vincoli, non solo l’aspetto.',
'Progetta un’etichetta per una scatola: 8 × 3 cm, scritta “MATITE”, bordo libero di 0,5 cm e fissaggio previsto con nastro. Produci prima il prototipo su carta e specifica come lo verifichi.',
'Rettangolo 8 × 3 cm; area interna utile 7 × 2 cm dopo margini di 0,5 cm su ogni lato. Scritta leggibile entro quell’area; fissaggio progettato senza coprirla. Verifica misure, margini e leggibilità; realizzazione solo autorizzata.',
[('Scrivi i vincoli','Sul tuo progetto indica dimensioni, funzione e condizioni di realizzazione.','“Bello” non sostituisce “15 × 4 cm”.'),('Costruisci il prototipo','Prova prima su carta con quote e posizione degli elementi.','Correggere qui evita rifare il prodotto finito.'),('Realizza e verifica','Usa solo strumenti autorizzati e confronta prodotto o prototipo con i vincoli.','Se non realizzi, dichiara che il test di uso reale resta da fare.')],
('Prototipo e confronto con vincoli','Prepara una lista di requisiti e verifica il modello prima e dopo la realizzazione.','Collega le scelte al problema da risolvere.'),
['Dimensioni e funzione sono esplicite','Il prototipo precede la realizzazione','La verifica indica che cosa è stato davvero provato'],
('Ho fatto il segnalibro largo 10 cm perché è più bello.','Hai perso il vincolo di larghezza previsto.','Torna al rettangolo 15 × 4 cm oppure chiedi una modifica motivata del requisito prima di realizzare.'),
'Usa un foglio con riquadro delle quote e sequenza numerata; se la manualità interferisce, un adulto esegue il taglio mentre tu controlli progetto e misure.',
'Sul tuo progetto scrivi tre vincoli e verifica prima il prototipo, poi il prodotto se realizzato.')

r('M13-07','Documentare un progetto con decisioni, fasi, risultati e modifiche tracciabili.',
'Dati di progetto fittizio: etichetta per scatola, 8 × 3 cm, scritta MATITE, margini 0,5 cm. Primo prototipo: scritta troppo lunga; modifica: lettere più piccole. Versione finale: scritta entra nell’area 7 × 2 cm. Scrivi una scheda di documentazione.',
['Registro obiettivo e vincoli con misure, titolo e area interna.','Sequenza: schizzo → prototipo → controllo → modifica delle lettere → verifica finale.','Distingui esito noto e ignoto: la scritta entra; tenuta del nastro non è ancora provata nei dati. Documento la modifica e il motivo.'],
'Scheda: “Obiettivo: identificare la scatola. Vincoli: 8 × 3 cm, margini 0,5 cm. Primo problema: scritta fuori area. Modifica: lettere ridotte. Esito: MATITE entra in 7 × 2 cm. Da verificare: fissaggio.”',
'Progetto fittizio: segnalibro 12 × 3 cm, titolo LEGGO. Primo modello: titolo vicino al bordo; modifica: spostato al centro. Finale: misure corrette, prova fra pagine non ancora fatta. Documenta.',
'Scheda con obiettivo, quote 12 × 3, sequenza e problema del titolo; modifica motivata “sposto al centro per lasciare spazio dal bordo”. Esito noto: misure corrette e titolo centrato. Da verificare: uso fra pagine. Non dichiarare riuscita una prova non eseguita.',
[('Raccogli le versioni','Sul tuo progetto conserva schizzo, prototipo e dati di controllo.','Numero o data aiutano a distinguere le versioni senza dati personali.'),('Spiega la modifica','Scrivi problema → scelta → motivo.','“Ho cambiato tutto” non permette di capire perché.'),('Registra l’esito','Separa vincoli rispettati, prove eseguite e verifiche ancora necessarie.','Una foto mostra l’aspetto, non ogni proprietà di funzionamento.')],
('Diario decisione-esito','Usa una riga per problema, modifica e verifica nella sequenza del progetto.','Rende ricostruibile il lavoro e il motivo delle scelte.'),
['I vincoli compaiono nella scheda','La modifica ha un motivo concreto','Esiti verificati e da verificare sono distinti'],
('Scrivo “funziona perfettamente” senza prova di fissaggio.','Non hai dati sulla tenuta.','Scrivi “scritta e dimensioni controllate; fissaggio da verificare”.'),
'Usa una scheda con cinque intestazioni e spazio per un disegno; puoi dettare motivi e risultati prima di trascriverli.',
'Nel tuo progetto conserva una modifica spiegata e una verifica ancora necessaria.')

r('M13-08','Leggere etichette e istruzioni e stimare consumo distinguendo potenza ed energia.',
'Etichetta didattica di lampada: potenza 10 W. Istruzioni: spegnere prima di pulire; pulire con panno asciutto secondo le indicazioni del prodotto; non aprire il dispositivo. Uso previsto: 3 ore al giorno. Calcola energia giornaliera e individua due istruzioni; non eseguire manutenzione.',
['Leggo 10 W come potenza, non energia totale. Uso E = P × t: 10 × 3 = 30 Wh = 0,03 kWh.','Estraggo due azioni dalle istruzioni: spegnere prima della pulizia; usare il panno indicato. Il divieto è non aprire il dispositivo.','Per cinque giorni uguali: 30 × 5 = 150 Wh = 0,15 kWh. Non ricavo il costo senza tariffa.'],
'Consumo giornaliero 30 Wh = 0,03 kWh; cinque giorni 150 Wh = 0,15 kWh. Etichetta, istruzioni e calcolo hanno funzioni diverse.',
'Etichetta didattica: lampada 8 W; uso 4 ore al giorno per 7 giorni. Istruzioni: scollegare secondo le indicazioni prima della manutenzione, non bagnare, non aprire. Calcola energia e scrivi un divieto e un dato mancante per il costo.',
'8 × 4 = 32 Wh/giorno; 32 × 7 = 224 Wh = 0,224 kWh. Divieto: non bagnare oppure non aprire. Per il costo manca la tariffa applicabile; non si inventa un prezzo. Non eseguire le azioni di manutenzione per esercitarti.',
[('Separa le informazioni','Sul tuo testo marca dato tecnico, azione richiesta e divieto.','W indica potenza; un’istruzione non è un numero di consumo.'),('Calcola l’energia','Scrivi potenza × ore e converti Wh in kWh dividendo per 1000.','Somma le ore solo se l’uso è quello descritto.'),('Controlla i limiti','Conserva i divieti e indica quali dati mancano per altri calcoli.','Non trasformare lettura di istruzioni in manutenzione reale.')],
('Lettura tecnica e controllo delle unità','Usa tre riquadri etichetta/istruzioni/consumo e una riga W × h = Wh.','Distingue dati tecnici, procedure e risultati quantitativi.'),
['Potenza ed energia non sono confuse','Ore e giorni sono conteggiati correttamente','Divieti e dati mancanti sono espliciti'],
('10 W per tre ore = 30 W.','Moltiplicando potenza per tempo ottieni energia.','Scrivi 30 Wh, poi 0,03 kWh.'),
'Trascrivi i dati in una tabella W/ore/giorni e lascia visibile 1000 Wh = 1 kWh; calcolatrice disponibile.',
'Su un’etichetta del libro separa un dato, un divieto e un calcolo di consumo.',category='discalculia')

r('M13-09','Usare un programma, scrivere istruzioni e simulare un robot distinguendo ambienti e risultati.',
'Tre attività su carta: A descrivi come salvare un disegno digitale come progetto modificabile e come immagine; B scrivi un algoritmo per una griglia; C simula un robot. Griglia: righe 1-3 dall’alto, colonne 1-3 da sinistra. Robot in (riga 3,colonna 1), rivolto a nord; meta (1,3). Comandi: AVANTI di una casella, DESTRA rotazione di 90° senza spostamento.',
['A: nel programma scelto usa il comando per salvare il progetto con nome “percorso”; poi il comando di esportazione per un’immagine. Le etichette esatte dipendono dal programma: il progetto conserva gli elementi modificabili, l’immagine non necessariamente.','B: algoritmo AVANTI, AVANTI, DESTRA, AVANTI, AVANTI. Traccia posizioni (3,1) → (2,1) → (1,1); rotazione verso est; → (1,2) → (1,3).','C: muovo un segnalino per i passi e ruoto una freccia per l’orientamento. Su robot reale comandi, sensori e ostacoli vanno verificati secondo il modello e il docente; qui è simulazione.'],
'Procedura digitale descritta con salvataggio modificabile ed esportazione distinti. Algoritmo di cinque comandi raggiunge (1,3) rivolto a est nella griglia; non prova il comportamento di un robot reale.',
'Nuova griglia 3 × 3: robot in (1,3) rivolto a sud, meta (3,1). Usa AVANTI e DESTRA. Indica inoltre differenza fra salvare il progetto in un programma e stampare una pagina.',
'AVANTI, AVANTI, DESTRA, AVANTI, AVANTI: (1,3) → (2,3) → (3,3), rotazione da sud a ovest, → (3,2) → (3,1). Salvataggio conserva un file per riaprirlo; stampa produce una pagina e non sostituisce il salvataggio. Per il programma reale verifica file riaperto e risultato della stampa separatamente.',
[('Definisci l’ambiente','Sul tuo compito indica programma digitale, algoritmo su carta o robot reale.','Non dare per verificata un’azione digitale che hai soltanto descritta.'),('Specifica i comandi','Definisci punto iniziale, orientamento, meta e significato di ogni comando.','DESTRA ruota: non sposta in una casella a destra.'),('Simula e controlla','Esegui un comando per volta segnando posizione e orientamento; per il digitale verifica l’output realmente prodotto.','Se un robot reale si comporta diversamente, controlla istruzioni e condizioni del suo modello.')],
('Tracciamento dell’esecuzione','Usa una tabella comando/posizione/orientamento e separa il risultato digitale dal percorso del robot.','Permette di trovare il primo comando che produce un risultato inatteso.'),
['Programma, algoritmo e robot sono distinti','Rotazione e spostamento seguono le definizioni','Risultati simulati e realmente verificati sono dichiarati'],
('DESTRA sposta il robot alla casella destra senza ruotarlo.','Nella definizione fornita il comando modifica solo orientamento.','Lascia la posizione invariata e ruota la freccia di 90°.'),
'Usa un segnalino e una freccia fisica per distinguere posizione e orientamento; mostra un comando alla volta e registra la riga prima di proseguire.',
'Per il tuo percorso registra comando, posizione e orientamento; per un programma controlla che il file salvato si riapra.')

expected = [x['id'] for x in json.loads((base/'inventario.json').read_text(encoding='utf-8-sig')) if 8 <= x['group'] <= 13]
assert len(rows) == 61 and sorted(x['id'] for x in rows) == sorted(expected)
required = {'id','goal','materials','techniques','example','steps','transfer','checks','error','home','adaptations','coach','sources'}
for row in rows:
    assert set(row) == required, row['id']
    assert len(row['techniques']) == 2 and 3 <= len(row['steps']) <= 5
    assert 2 <= len(row['checks']) <= 4 and len(row['home']) == 3
    assert 1 <= len(row['adaptations']) <= 3 and 2 <= len(row['example']['work']) <= 5
    assert set(row['example']) == {'task','work','result'}
    assert set(row['transfer']) == {'task','check'}
    assert set(row['error']) == {'wrong','why','fix'}
    for a in row['adaptations']:
        assert set(a) == {'stage','difficulty','categories','signal','aid','preserve','verify'}
        assert set(a['categories']) <= {'dislessia','disortografia','disgrafia','discalculia','trasversale'}
    assert all(isinstance(v,str) and v.strip() for v in row['sources'])

(base/'guide-b.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'Guide salvate: {len(rows)}; schema e ID corretti.')


